public void jump() {
    if (flying) {
        // Fly up
        velocity.y = 6.0f;
        return;
    }
    if (onGround && !swimming) {
        velocity.y = sprinting ? SPRINT_JUMP_FORCE : JUMP_FORCE;
        onGround = false;

        // Jumping costs hunger
        if (sprinting) {
            saturation -= 0.2f;
        } else {
            saturation -= 0.05f;
        }
    } else if (swimming) {
        // Swim up
        velocity.y = 2.0f;
    }
}

public void descend() {
    if (flying) {
        velocity.y = -6.0f;
    }
}

