/**
 * 15x15 crosshair in the classic Minecraft style: a white plus with a
 * 1px dark outline so it stays readable against any background.
 */
private int makeCrosshair() {
    int s = CROSSHAIR_SIZE;
    int[] p = new int[s * s];

    int c = s / 2;  // centre pixel (7 for 15x15)
    int armLen = 6; // length of each arm from centre
    int gap = 1;    // transparent gap around centre

    for (int i = -armLen; i <= armLen; i++) {
        int ax = c + i;
        // Horizontal arm
        plotCrosshairPixel(p, s, ax, c, i, gap, false);
        // Vertical arm
        plotCrosshairPixel(p, s, c, ax, i, gap, true);
    }

    // Centre dot (optional, 1px)
    set(p, s, c, c, 0xFF000000);

    return upload(p, s, s, false);
}

/**
 * Plot a single pixel of the crosshair arm with its outline.
 * Draws the dark outline first, then the white centre on top.
 */
private void plotCrosshairPixel(int[] p, int s, int x, int y, int dist, int gap, boolean vertical) {
    if (Math.abs(dist) <= gap) return; // skip the transparent gap

    int color;
    if (dist == -armLen() || dist == armLen() || Math.abs(dist) == armLen()) {
        // Tip pixels are white
        color = 0xFFFFFFFF;
    } else {
        color = 0xFFFFFFFF;
    }

    // Draw the main white pixel
    set(p, s, x, y, color);

    // Draw dark outline around it
    if (dist > gap) {
        // Outline on the "outside" of the arm
        if (vertical) {
            set(p, s, x, y + 1, 0xFF000000);
            set(p, s, x - 1, y, 0xFF000000);
            set(p, s, x + 1, y, 0xFF000000);
        } else {
            set(p, s, x + 1, y, 0xFF000000);
            set(p, s, x, y - 1, 0xFF000000);
            set(p, s, x, y + 1, 0xFF000000);
        }
    } else {
        // Outline on the other side
        if (vertical) {
            set(p, s, x, y - 1, 0xFF000000);
            set(p, s, x - 1, y, 0xFF000000);
            set(p, s, x + 1, y, 0xFF000000);
        } else {
            set(p, s, x - 1, y, 0xFF000000);
            set(p, s, x, y - 1, 0xFF000000);
            set(p, s, x, y + 1, 0xFF000000);
        }
    }
}

private int armLen() { return 6; }

