package com.voxelgame.ui.screen;

import com.voxelgame.item.*;
import com.voxelgame.ui.GuiAssets;
import com.voxelgame.ui.UIRenderer;
import com.voxelgame.ui.FontRenderer;
import com.voxelgame.world.BlockType;
import org.lwjgl.glfw.GLFW;

import java.util.ArrayList;
import java.util.List;

import static com.voxelgame.core.Language.tr;

/**
 * Crafting screen with 2x2 (inventory) and 3x3 (crafting table) grids.
 */
public class CraftingScreen extends Screen {

    public interface Callbacks {
        Inventory inventory();
        void close();
    }

    private static final int SLOT = GuiAssets.SLOT_SIZE;
    private static final int ICON = GuiAssets.ICON_SIZE;
    private static final int GRID_GAP = 4;
    private static final int SECTION_GAP = 16;

    private final Callbacks callbacks;
    private final boolean isCraftingTable; // 3x3 if true, 2x2 if false

    // Crafting grid slots
    private final ItemStack[] grid;
    private final int gridSize;
    private ItemStack resultSlot;

    // Layout
    private int panelX, panelY, panelW, panelH;
    private int gridStartX, gridStartY;
    private int resultX, resultY;
    private int outputX, outputY;

    public CraftingScreen(Callbacks callbacks, boolean isCraftingTable) {
        this.callbacks = callbacks;
        this.isCraftingTable = isCraftingTable;
        this.gridSize = isCraftingTable ? 3 : 2;
        this.grid = new ItemStack[gridSize * gridSize];
        for (int i = 0; i < grid.length; i++) grid[i] = new ItemStack(BlockType.AIR, 0);
        this.resultSlot = new ItemStack(BlockType.AIR, 0);
    }

    @Override
    public void layout(int w, int h) {
        int gridPixelSize = gridSize * SLOT;
        int totalW = gridPixelSize + SECTION_GAP + SLOT + SECTION_GAP + SLOT;
        int totalH = gridPixelSize;

        panelW = totalW + 20;
        panelH = totalH + 40;
        panelX = (w - panelW) / 2;
        panelY = (h - panelH) / 2;

        gridStartX = panelX + 10;
        gridStartY = panelY + 20;

        resultX = gridStartX + gridPixelSize + SECTION_GAP;
        resultY = gridStartY + (gridPixelSize / 2) - SLOT / 2;

        outputX = resultX + SLOT + SECTION_GAP;
        outputY = resultY;
    }

    @Override
    public void render(UIRenderer ui, FontRenderer font, int w, int h) {
        // Background
        ui.drawRect(0, 0, w, h, 0xC8000000);

        // Panel
        ui.drawPanel(panelX, panelY, panelW, panelH);

        // Title
        String title = isCraftingTable ? tr("container.crafting") : tr("container.inventory");
        font.drawCentered(title, panelX + panelW / 2, panelY + 4, GuiAssets.TEXT_NORMAL);

        // Grid slots
        for (int y = 0; y < gridSize; y++) {
            for (int x = 0; x < gridSize; x++) {
                int sx = gridStartX + x * SLOT;
                int sy = gridStartY + y * SLOT;
                ui.drawSlot(sx, sy);
                ItemStack item = grid[y * gridSize + x];
                if (!item.isEmpty()) {
                    drawItem(ui, item, sx + 1, sy + 1);
                }
            }
        }

        // Arrow
        int arrowX = resultX;
        int arrowY = resultY + 2;
        font.drawCentered("→", arrowX + SLOT / 2, arrowY + 6, GuiAssets.TEXT_HINT);

        // Result slot
        ui.drawSlot(outputX, outputY);
        if (!resultSlot.isEmpty()) {
            drawItem(ui, resultSlot, outputX + 1, outputY + 1);
        }
    }

    private void drawItem(UIRenderer ui, ItemStack item, int x, int y) {
        // Draw item icon (simplified - just a colored rect for now)
        int color = 0xFF808080;
        if (item.isBlock()) {
            color = item.getBlockType().color;
        } else if (item.getItem() != null) {
            color = 0xFFC0C0C0;
        }
        ui.drawRect(x, y, ICON, ICON, color);
    }

    @Override
    public boolean onMouseButton(int button, int mx, int my) {
        if (button != 0) return false;

        // Check grid slots
        for (int y = 0; y < gridSize; y++) {
            for (int x = 0; x < gridSize; x++) {
                int sx = gridStartX + x * SLOT;
                int sy = gridStartY + y * SLOT;
                if (mx >= sx && mx < sx + SLOT && my >= sy && my < sy + SLOT) {
                    // Place/remove item from grid
                    ItemStack cursor = callbacks.inventory().getSelectedItem();
                    if (!cursor.isEmpty()) {
                        grid[y * gridSize + x] = new ItemStack(cursor.getItem() != null ? cursor.getItem() : null, 1);
                        if (grid[y * gridSize + x].isEmpty()) {
                            grid[y * gridSize + x] = new ItemStack(cursor.getBlockType(), 1);
                        }
                    } else {
                        grid[y * gridSize + x] = new ItemStack(BlockType.AIR, 0);
                    }
                    updateResult();
                    return true;
                }
            }
        }

        // Check result slot
        if (mx >= outputX && mx < outputX + SLOT && my >= outputY && my < outputY + SLOT) {
            if (!resultSlot.isEmpty()) {
                // Take result
                callbacks.inventory().addItem(resultSlot.getItem() != null ? resultSlot.getItem() : null,
                    resultSlot.getCount());
                if (resultSlot.isBlock()) {
                    callbacks.inventory().addItem(resultSlot.getBlockType(), resultSlot.getCount());
                }
                // Consume grid items
                for (ItemStack g : grid) {
                    if (!g.isEmpty()) g.remove(1);
                }
                updateResult();
            }
            return true;
        }

        return false;
    }

    @Override
    public boolean onKey(int key, int scancode, int action, int mods) {
        if (key == GLFW.GLFW_KEY_ESCAPE) {
            callbacks.close();
            return true;
        }
        return false;
    }

    private void updateResult() {
        resultSlot = new ItemStack(BlockType.AIR, 0);

        // Check all recipes
        for (Recipe recipe : RecipeRegistry.RECIPES) {
            if (recipe.matches(grid, gridSize)) {
                resultSlot = recipe.getResult().copy();
                return;
            }
        }
    }
}

package com.voxelgame.world.entity;

import com.voxelgame.world.World;
import com.voxelgame.world.BlockType;
import org.joml.Vector3f;

/**
 * Base entity class for mobs (animals, monsters).
 */
public abstract class Mob {

    public enum MobType {
        PIG("Pig", 10, 2.0f, 0.5f),
        COW("Cow", 10, 2.0f, 0.5f),
        SHEEP("Sheep", 8, 2.0f, 0.5f),
        CHICKEN("Chicken", 4, 1.5f, 0.3f),
        ZOMBIE("Zombie", 20, 2.0f, 0.6f),
        SKELETON("Skeleton", 20, 2.0f, 0.6f),
        CREEPER("Creeper", 20, 2.0f, 0.5f),
        SPIDER("Spider", 16, 2.5f, 0.8f);

        public final String name;
        public final int maxHealth;
        public final float speed;
        public final float damage;

        MobType(String name, int maxHealth, float speed, float damage) {
            this.name = name;
            this.maxHealth = maxHealth;
            this.speed = speed;
            this.damage = damage;
        }

        public boolean isHostile() {
            return this == ZOMBIE || this == SKELETON || this == CREEPER || this == SPIDER;
        }
    }

    protected Vector3f position;
    protected Vector3f velocity;
    protected World world;
    protected MobType type;
    protected int health;
    protected boolean onGround = false;

    // AI
    protected float aiTick = 0;
    protected float wanderTimer = 0;
    protected float targetX, targetZ;
    protected boolean hasTarget = false;

    // Animation
    protected float limbSwing = 0;
    protected float limbSwingAmount = 0;

    public Mob(MobType type, World world, float x, float y, float z) {
        this.type = type;
        this.world = world;
        this.position = new Vector3f(x, y, z);
        this.velocity = new Vector3f(0, 0, 0);
        this.health = type.maxHealth;
    }

    public void update(float dt) {
        // AI update
        aiTick += dt;
        updateAI(dt);

        // Physics
        velocity.y -= 28.0f * dt; // gravity

        // Move
        moveAxis(velocity.x * dt, 0, 0);
        moveAxis(0, velocity.y * dt, 0);
        moveAxis(0, 0, velocity.z * dt);

        // Friction
        velocity.x *= 0.85f;
        velocity.z *= 0.85f;

        // Animation
        limbSwing += dt * 4.0f;
        limbSwingAmount = java.lang.Math.min(1.0f, java.lang.Math.abs(velocity.x) + java.lang.Math.abs(velocity.z));
    }

    protected void updateAI(float dt) {
        wanderTimer -= dt;

        if (!hasTarget && wanderTimer <= 0) {
            // Pick random wander target
            targetX = position.x + (float) (Math.random() - 0.5) * 10;
            targetZ = position.z + (float) (Math.random() - 0.5) * 10;
            hasTarget = true;
            wanderTimer = 3.0f + (float) Math.random() * 5.0f;
        }

        if (hasTarget) {
            float dx = targetX - position.x;
            float dz = targetZ - position.z;
            float dist = (float) Math.sqrt(dx * dx + dz * dz);
            if (dist < 0.5f) {
                hasTarget = false;
            } else {
                velocity.x = (dx / dist) * type.speed;
                velocity.z = (dz / dist) * type.speed;
            }
        }
    }

    private void moveAxis(float dx, float dy, float dz) {
        if (dx == 0 && dy == 0 && dz == 0) return;

        Vector3f newPos = new Vector3f(position);
        newPos.x += dx;
        newPos.y += dy;
        newPos.z += dz;

        if (!collides(newPos)) {
            position.set(newPos);
            if (dy != 0) onGround = false;
        } else {
            if (dy < 0) {
                // Hit ground
                onGround = true;
                velocity.y = 0;
            } else if (dy > 0) {
                velocity.y = 0;
            } else {
                velocity.x = 0;
                velocity.z = 0;
                hasTarget = false; // Blocked, pick new target
            }
        }
    }

    private boolean collides(Vector3f pos) {
        float w = 0.4f;
        float h = 1.7f;
        int minX = (int) Math.floor(pos.x - w);
        int maxX = (int) Math.floor(pos.x + w);
        int minY = (int) Math.floor(pos.y);
        int maxY = (int) Math.floor(pos.y + h);
        int minZ = (int) Math.floor(pos.z - w);
        int maxZ = (int) Math.floor(pos.z + w);

        for (int x = minX; x <= maxX; x++) {
            for (int y = minY; y <= maxY; y++) {
                for (int z = minZ; z <= maxZ; z++) {
                    if (world.isSolid(x, y, z)) return true;
                }
            }
        }
        return false;
    }

    public void takeDamage(int amount) {
        health -= amount;
    }

    public boolean isDead() {
        return health <= 0;
    }

    public MobType getType() { return type; }
    public Vector3f getPosition() { return position; }
    public int getHealth() { return health; }
    public float getLimbSwing() { return limbSwing; }
    public float getLimbSwingAmount() { return limbSwingAmount; }
}

