/**
 * Furnace smelting screen.
 */
public class FurnaceScreen extends Screen {

    public interface Callbacks {
        Inventory inventory();
        void close();
    }

    private static final int SLOT = GuiAssets.SLOT_SIZE;
    private static final int SECTION_GAP = 16;

    private final Callbacks callbacks;
    private ItemStack inputSlot;
    private ItemStack fuelSlot;
    private ItemStack outputSlot;
    private float smeltProgress = 0;
    private float fuelTime = 0;
    private float maxFuelTime = 0;

    private int panelX, panelY, panelW, panelH;
    private int inputX, inputY;
    private int fuelX, fuelY;
    private int outputX, outputY;
    private int flameX, flameY;
    private int progressX, progressY;

    public FurnaceScreen(Callbacks callbacks) {
        this.callbacks = callbacks;
        this.inputSlot = new ItemStack(BlockType.AIR, 0);
        this.fuelSlot = new ItemStack(BlockType.AIR, 0);
        this.outputSlot = new ItemStack(BlockType.AIR, 0);
    }

    @Override
    public void render(UIRenderer ui, FontRenderer font, int w, int h) {
        ui.drawRect(0, 0, w, h, 0xC8000000);
        ui.drawPanel(panelX, panelY, panelW, panelH);

        String title = tr("container.furnace");
        font.drawCentered(ui, title, panelX + panelW / 2, panelY + 6, GuiAssets.TEXT_NORMAL);

        // Input slot (top)
        ui.drawSlot(inputX, inputY);
        if (!inputSlot.isEmpty()) drawItemIcon(ui, inputSlot, inputX + 1, inputY + 1);

        // Fuel slot (bottom left)
        ui.drawSlot(fuelX, fuelY);
        if (!fuelSlot.isEmpty()) drawItemIcon(ui, fuelSlot, fuelX + 1, fuelY + 1);

        // Flame
        int flameHeight = (maxFuelTime > 0) ? (int) (12 * fuelTime / maxFuelTime) : 0;
        if (flameHeight > 0) {
            ui.drawRect(flameX + 2, flameY + 14 - flameHeight, 8, flameHeight, 0xFFFF8000);
        }

        // Progress arrow
        int progressWidth = (int) (24 * smeltProgress);
        if (progressWidth > 0) {
            ui.drawRect(progressX, progressY + 2, progressWidth, 8, 0xFF00FF00);
        }

        // Output slot
        ui.drawSlot(outputX, outputY);
        if (!outputSlot.isEmpty()) drawItemIcon(ui, outputSlot, outputX + 1, outputY + 1);
    }

    private void drawItemIcon(UIRenderer ui, ItemStack item, int x, int y) {
        int color = 0xFF808080;
        if (item.isBlock()) color = item.getBlockType().color | 0xFF000000;
        else if (item.getItem() != null) color = 0xFFC0C0C0;
        ui.drawRect(x, y, GuiAssets.ICON_SIZE, GuiAssets.ICON_SIZE, color);
    }

    @Override
    public boolean onMouseButton(int button, int mx, int my) {
        // Input slot
        if (mx >= inputX && mx < inputX + SLOT && my >= inputY && my < inputY + SLOT) {
            handleSlotClick("input", button);
            return true;
        }
        // Fuel slot
        if (mx >= fuelX && mx < fuelX + SLOT && my >= fuelY && my < fuelY + SLOT) {
            handleSlotClick("fuel", button);
            return true;
        }
        // Output slot
        if (mx >= outputX && mx < outputX + SLOT && my >= outputY && my < outputY + SLOT) {
            handleSlotClick("output", button);
            return true;
        }
        return false;
    }

    private void handleSlotClick(String slot, int button) {
        ItemStack cursor = callbacks.inventory().getSelectedItem();
        ItemStack target = switch (slot) {
            case "input" -> inputSlot;
            case "fuel" -> fuelSlot;
            case "output" -> outputSlot;
            default -> null;
        };
        if (target == null) return;

        if (button == 0) { // Left click
            if (cursor.isEmpty() && !target.isEmpty()) {
                // Take from slot
                if (slot.equals("output")) {
                    callbacks.inventory().addItem(target.getItem(), target.getCount());
                    if (target.isBlock()) callbacks.inventory().addItem(target.getBlockType(), target.getCount());
                    target.clear();
                }
            } else if (!cursor.isEmpty()) {
                // Place into slot
                if (target.isEmpty()) {
                    if (slot.equals("input") && canSmelt(cursor)) {
                        inputSlot = cursor.copy();
                        cursor.clear();
                    } else if (slot.equals("fuel") && isFuel(cursor)) {
                        fuelSlot = cursor.copy();
                        fuelTime += getFuelTime(cursor);
                        maxFuelTime = fuelTime;
                        cursor.clear();
                    }
                }
            }
        }
    }

    private boolean canSmelt(ItemStack item) {
        return getSmeltingResult(item) != null;
    }

    private boolean isFuel(ItemStack item) {
        return getFuelTime(item) > 0;
    }

    private float getFuelTime(ItemStack item) {
        if (item.isBlock()) {
            if (item.getBlockType() == BlockType.COAL_BLOCK) return 1600;
        }
        if (item.isItem()) {
            if (item.getItem() == ItemRegistry.COAL) return 160;
            if (item.getItem() == ItemRegistry.STICK) return 10;
        }
        if (item.isBlock()) {
            BlockType bt = item.getBlockType();
            if (bt == BlockType.OAK_PLANKS) return 15;
            if (bt == BlockType.OAK_LOG) return 15;
        }
        return 0;
    }

    private ItemStack getSmeltingResult(ItemStack input) {
        if (input.isBlock()) {
            BlockType bt = input.getBlockType();
            if (bt == BlockType.IRON_ORE) return new ItemStack(ItemRegistry.IRON_INGOT, 1);
            if (bt == BlockType.GOLD_ORE) return new ItemStack(ItemRegistry.GOLD_INGOT, 1);
            if (bt == BlockType.SAND) return new ItemStack(BlockType.GLASS, 1);
            if (bt == BlockType.COBBLESTONE) return new ItemStack(BlockType.STONE, 1);
            if (bt == BlockType.OAK_LOG) return new ItemStack(ItemRegistry.COAL, 1);
        }
        if (input.isItem()) {
            Item item = input.getItem();
            if (item == ItemRegistry.RAW_PORK) return new ItemStack(ItemRegistry.COOKED_PORK, 1);
            if (item == ItemRegistry.RAW_BEEF) return new ItemStack(ItemRegistry.COOKED_BEEF, 1);
            if (item == ItemRegistry.RAW_CHICKEN) return new ItemStack(ItemRegistry.COOKED_CHICKEN, 1);
            if (item == ItemRegistry.RAW_MUTTON) return new ItemStack(ItemRegistry.COOKED_MUTTON, 1);
        }
        return null;
    }

    public void update() {
        if (fuelTime > 0) fuelTime -= 0.016f;

        if (!inputSlot.isEmpty() && fuelTime > 0) {
            ItemStack result = getSmeltingResult(inputSlot);
            if (result != null && (outputSlot.isEmpty() || outputSlot.equals(result))) {
                smeltProgress += 0.01f;
                if (smeltProgress >= 1.0f) {
                    if (outputSlot.isEmpty()) {
                        outputSlot = result.copy();
                    } else {
                        outputSlot.add(result.getCount());
                    }
                    inputSlot.remove(1);
                    smeltProgress = 0;
                }
            }
        } else {
            smeltProgress = 0;
        }
    }

    @Override
    public boolean onKey(int key, int scancode, int action, int mods) {
        if (key == GLFW.GLFW_KEY_ESCAPE) {
            callbacks.close();
            return true;
        }
        return false;
    }
}

