package com.voxelgame.ui.screen;

import com.voxelgame.item.*;
import com.voxelgame.ui.GuiAssets;
import com.voxelgame.ui.UIRenderer;
import com.voxelgame.ui.FontRenderer;
import com.voxelgame.world.BlockType;
import org.lwjgl.glfw.GLFW;

import static com.voxelgame.core.Language.tr;

/**
 * Chest storage screen with 27 slots.
 */
public class ChestScreen extends Screen {

    public interface Callbacks {
        Inventory inventory();
        void close();
    }

    private static final int SLOT = GuiAssets.SLOT_SIZE;
    private static final int COLS = 9;
    private static final int ROWS = 3;

    private final Callbacks callbacks;
    private final ItemStack[] chestSlots;

    private int panelX, panelY, panelW, panelH;
    private int chestStartX, chestStartY;

    public ChestScreen(Callbacks callbacks) {
        this.callbacks = callbacks;
        this.chestSlots = new ItemStack[27];
        for (int i = 0; i < 27; i++) chestSlots[i] = new ItemStack(BlockType.AIR, 0);
    }

    @Override
    public void render(UIRenderer ui, FontRenderer font, int w, int h) {
        ui.drawRect(0, 0, w, h, 0xC8000000);
        ui.drawPanel(panelX, panelY, panelW, panelH);

        String title = tr("container.chest");
        font.drawCentered(ui, title, panelX + panelW / 2, panelY + 6, GuiAssets.TEXT_NORMAL);

        // Chest slots
        for (int y = 0; y < ROWS; y++) {
            for (int x = 0; x < COLS; x++) {
                int sx = chestStartX + x * SLOT;
                int sy = chestStartY + y * SLOT;
                ui.drawSlot(sx, sy);
                ItemStack item = chestSlots[y * COLS + x];
                if (!item.isEmpty()) {
                    drawItemIcon(ui, item, sx + 1, sy + 1);
                }
            }
        }
    }

    private void drawItemIcon(UIRenderer ui, ItemStack item, int x, int y) {
        int color = 0xFF808080;
        if (item.isBlock()) color = item.getBlockType().color | 0xFF000000;
        else if (item.getItem() != null) color = 0xFFC0C0C0;
        ui.drawRect(x, y, GuiAssets.ICON_SIZE, GuiAssets.ICON_SIZE, color);
    }

    @Override
    public boolean onMouseButton(int button, int mx, int my) {
        for (int y = 0; y < ROWS; y++) {
            for (int x = 0; x < COLS; x++) {
                int sx = chestStartX + x * SLOT;
                int sy = chestStartY + y * SLOT;
                if (mx >= sx && mx < sx + SLOT && my >= sy && my < sy + SLOT) {
                    handleSlotClick(y * COLS + x, button);
                    return true;
                }
            }
        }
        return false;
    }

    private void handleSlotClick(int slot, int button) {
        ItemStack cursor = callbacks.inventory().getSelectedItem();
        ItemStack target = chestSlots[slot];

        if (button == 0) { // Left click
            if (cursor.isEmpty() && !target.isEmpty()) {
                // Take from chest
                ItemStack taken = target.copy();
                callbacks.inventory().addItem(taken.getItem(), taken.getCount());
                if (taken.isBlock()) callbacks.inventory().addItem(taken.getBlockType(), taken.getCount());
                target.clear();
            } else if (!cursor.isEmpty()) {
                // Place into chest
                if (target.isEmpty()) {
                    chestSlots[slot] = cursor.copy();
                    cursor.clear();
                } else if (target.equals(cursor)) {
                    target.add(cursor.getCount());
                    cursor.clear();
                }
            }
        }
    }

    @Override
    public boolean onKey(int key, int scancode, int action, int mods) {
        if (key == GLFW.GLFW_KEY_ESCAPE) {
            callbacks.close();
            return true;
        }
        return false;
    }
}

package com.voxelgame.ui.screen;

import com.voxelgame.item.*;
import com.voxelgame.rendering.TextureAtlas;
import com.voxelgame.ui.FontRenderer;
import com.voxelgame.ui.GuiAssets;
import com.voxelgame.ui.UIRenderer;
import com.voxelgame.world.BlockType;

import static com.voxelgame.core.Language.tr;

/**
 * Crafting table screen - 3x3 grid + result slot.
 */
public class CraftingScreen extends Screen {

    public interface Callbacks {
        Inventory inventory();
        void onClose();
    }

    private static final int SLOT = GuiAssets.SLOT_SIZE;
    private static final int ICON = GuiAssets.ICON_SIZE;
    private static final int SECTION_GAP = 20;

    private final Callbacks callbacks;
    private final TextureAtlas atlas;
    private final ItemStack[] grid = new ItemStack[9];
    private ItemStack resultSlot = new ItemStack(BlockType.AIR, 0);

    private int panelX, panelY, panelW, panelH;
    private int gridStartX, gridStartY;
    private int outputX, outputY;

    public CraftingScreen(Callbacks callbacks, TextureAtlas atlas) {
        this.callbacks = callbacks;
        this.atlas = atlas;
        for (int i = 0; i < 9; i++) grid[i] = new ItemStack(BlockType.AIR, 0);
    }

    @Override
    public boolean rendersWorld() { return false; }

    @Override
    protected void layout() {
        int gridSize = 3 * SLOT;
        panelW = gridSize + SECTION_GAP + SLOT + SECTION_GAP + SLOT + 20;
        panelH = gridSize + 40;
        panelX = (width - panelW) / 2;
        panelY = (height - panelH) / 2;
        gridStartX = panelX + 10;
        gridStartY = panelY + 25;
        outputX = gridStartX + gridSize + SECTION_GAP + 10;
        outputY = gridStartY + SLOT;
    }

    @Override
    protected void renderBackground(UIRenderer ui, FontRenderer font, GuiAssets gui) {
        ui.fillRect(0, 0, width, height, 0xC8000000);
        ui.drawNineSlice(gui.panel, panelX, panelY, panelW, panelH,
            GuiAssets.BORDER, GuiAssets.WIDGET, 0xFFFFFFFF);
        font.draw(ui, tr("container.crafting"), gridStartX, panelY + 8, GuiAssets.TEXT_TITLE);
    }

    @Override
    protected void renderForeground(UIRenderer ui, FontRenderer font, GuiAssets gui, float mx, float my) {
        // Grid
        for (int y = 0; y < 3; y++) {
            for (int x = 0; x < 3; x++) {
                int sx = gridStartX + x * SLOT;
                int sy = gridStartY + y * SLOT;
                ui.drawSprite(gui.slot, sx, sy, SLOT, SLOT);
                ItemStack item = grid[y * 3 + x];
                if (!item.isEmpty()) drawItemIcon(ui, item, sx + 1, sy + 1);
            }
        }

        // Arrow
        font.draw(ui, "→", outputX - SECTION_GAP / 2, outputY + 6, GuiAssets.TEXT_HINT);

        // Output
        ui.drawSprite(gui.slot, outputX, outputY, SLOT, SLOT);
        if (!resultSlot.isEmpty()) drawItemIcon(ui, resultSlot, outputX + 1, outputY + 1);
    }

    private void drawItemIcon(UIRenderer ui, ItemStack item, int x, int y) {
        if (item.isBlock()) {
            TextureAtlas.TextureCoords uv = atlas.getCoords(item.getBlockType().id, 2);
            ui.drawTexture(atlas.getTexture().getId(), x, y, ICON, ICON,
                uv.u1, uv.v2, uv.u2, uv.v1, 0xFFFFFFFF);
        }
    }

    @Override
    public boolean mouseClicked(float mx, float my, int button) {
        // Grid
        for (int y = 0; y < 3; y++) {
            for (int x = 0; x < 3; x++) {
                int sx = gridStartX + x * SLOT;
                int sy = gridStartY + y * SLOT;
                if (mx >= sx && mx < sx + SLOT && my >= sy && my < sy + SLOT) {
                    handleGridClick(x, y, button);
                    return true;
                }
            }
        }

        // Output
        if (mx >= outputX && mx < outputX + SLOT && my >= outputY && my < outputY + SLOT) {
            if (!resultSlot.isEmpty()) {
                ItemStack cursor = getMouseItem();
                if (cursor.isEmpty()) {
                    setMouseItem(resultSlot.copy());
                    for (ItemStack g : grid) g.remove(1);
                    updateResult();
                }
            }
            return true;
        }
        return false;
    }

    private void handleGridClick(int x, int y, int button) {
        ItemStack cursor = getMouseItem();
        if (button == 0) {
            if (grid[y * 3 + x].isEmpty() && !cursor.isEmpty()) {
                grid[y * 3 + x] = cursor.copy();
                grid[y * 3 + x].setCount(1);
            } else if (!grid[y * 3 + x].isEmpty() && cursor.isEmpty()) {
                grid[y * 3 + x] = new ItemStack(BlockType.AIR, 0);
            }
        }
        updateResult();
    }

    private void updateResult() {
        resultSlot = new ItemStack(BlockType.AIR, 0);
        for (Recipe recipe : RecipeRegistry.RECIPES) {
            if (recipe.matches(grid, 3)) {
                resultSlot = recipe.getResult().copy();
                return;
            }
        }
    }

    // Mouse item helpers (stored in inventory temporarily)
    private ItemStack getMouseItem() {
        return callbacks.inventory().getSelectedItem(); // simplified
    }
    private void setMouseItem(ItemStack item) {
        callbacks.inventory().addItem(item.getItem() != null ? item.getItem() : null, item.getCount());
    }

    @Override
