public void renderMobs(World world, Shader shader, Camera camera) {
    var mobs = world.getMobs();
    if (mobs.isEmpty()) return;

    glEnable(GL_DEPTH_TEST);
    glEnable(GL_CULL_FACE);
    glCullFace(GL_BACK);
    glDisable(GL_BLEND);

    shader.bind();
    shader.setUniformMat4("projection", camera.getProjectionMatrix());
    shader.setUniformMat4("view", camera.getViewMatrix());
    shader.setUniform1i("blockTextures", 0);
    shader.setUniform1f("lightLevel", 1.0f);
    shader.setUniform3f("sunColor", new Vector3f(1.0f, 1.0f, 1.0f));

    glActiveTexture(GL_TEXTURE0);
    textureAtlas.bindArray();

    org.joml.Matrix4f model = new org.joml.Matrix4f();
    for (var mob : mobs) {
        Vector3f pos = mob.getPosition();
        model.identity();
        model.translate(pos.x, pos.y, pos.z);
        // Simple mob scale
        model.scale(0.6f, 1.8f, 0.6f);

        shader.setUniformMat4("model", model);

        // Use a different block color for each mob type
        BlockType mobBlock = getMobBlockType(mob);
        heldItemCube.render(textureAtlas, mobBlock, shader);
    }

    textureAtlas.unbindArray();
    shader.unbind();
}

private BlockType getMobBlockType(com.voxelgame.world.entity.Mob mob) {
