        case PIG -> BlockType.SAND;
        case COW -> BlockType.DIRT;
        case SHEEP -> BlockType.SNOW;
        case CHICKEN -> BlockType.SAND;
        case ZOMBIE -> BlockType.GREEN_CONCRETE;
        case SKELETON -> BlockType.WHITE_CONCRETE;
        case CREEPER -> BlockType.GREEN_CONCRETE;
        case SPIDER -> BlockType.COAL_BLOCK;
        default -> BlockType.STONE;
    };
}

