    mobShader.setUniform1f("daylight", daylight);
    mobShader.setUniform3f("cameraPos", camera.getPosition());
    mobShader.setUniform3f("skyColor", new Vector3f(0.6f, 0.7f, 1.0f));
    mobShader.setUniform1f("fogStart", 80.0f);
    mobShader.setUniform1f("fogEnd", 120.0f);
