private void renderMobModel(com.voxelgame.world.entity.Mob mob, Camera camera) {
    MobModel model = getMobModel(mob.getType());
    Vector3f pos = mob.getPosition();

    // Calculate yaw to face movement direction or player
    float yaw = 0;
    if (mob.getVelocity().lengthSquared() > 0.01f) {
        yaw = (float) Math.toDegrees(Math.atan2(mob.getVelocity().x, mob.getVelocity().z));
    } else {
        // Face player
        Vector3f toPlayer = new Vector3f(camera.getPosition()).sub(pos);
        yaw = (float) Math.toDegrees(Math.toRadians(Math.atan2(toPlayer.x, toPlayer.z)));
    }

    model.render(new Matrix4f(), mobShader, textureAtlas, heldItemCube,
        pos.x, pos.y, pos.z, yaw);
}

private MobModel getMobModel(com.voxelgame.world.entity.Mob.MobType type) {
    return switch (type) {
        case PIG -> MobModel.create(MobModel.MobModelType.PIG);
        case COW -> MobModel.create(MobModel.MobModelType.COW);
        case SHEEP -> MobModel.create(MobModel.MobModelType.SHEEP);
        case CHICKEN -> MobModel.create(MobModel.MobModelType.CHICKEN);
        case ZOMBIE -> MobModel.create(MobModel.MobModelType.ZOMBIE);
        case SKELETON -> MobModel.create(MobModel.MobModelType.SKELETON);
        case CREEPER -> MobModel.create(MobModel.MobModelType.CREEPER);
        case SPIDER -> MobModel.create(MobModel.MobModelType.SPIDER);
    };
}

