package com.voxelgame.world.entity;

import com.voxelgame.rendering.Shader;
import com.voxelgame.rendering.TextureAtlas;
import com.voxelgame.world.BlockType;
import org.joml.Matrix4f;
import org.joml.Vector3f;

/**
 * Mob model that uses a texture atlas with specific UV regions for each body part,
 * mimicking Minecraft's mob rendering system.
 *
 * Each mob has a texture map where different regions correspond to different body parts.
 * We render each part as a textured box with proper UVs.
 */
public class MobModel {

    public enum MobType {
        PIG, COW, SHEEP, CHICKEN, ZOMBIE, SKELETON, CREEPER, SPIDER
    }

    // UV coordinates in the mob texture atlas (each mob has its own 64x64 texture)
    // Format: (u, v, width, height) in pixel coordinates
    private static class UV {
        float u, v, w, h;
        UV(float u, float v, float w, float h) { this.u = u; this.v = v; this.w = w; this.h = h; }
    }

    private final MobType type;

    // Body part definitions: offsetX, offsetY, offsetZ, sizeX, sizeY, sizeZ
    private final float[][] parts;
    private final float width, height;

    // Mob texture tint
    private final float tintR, tintG, tintB;

    // Animation state
    private float limbSwing = 0;
    private float limbSwingAmount = 0;

    private MobType mobType;

    private MobType getMobType() { return mobType; }

    private MobModel(MobType type, float[][] parts, float w, float h,
                     float tr, float tg, float tb) {
        this.type = type;
        this.parts = parts;
        this.width = w;
        this.height = h;
        this.tintR = tr; this.tintG = tg; this.tintB = tb;
    }

    public static MobModel create(MobType type) {
        return switch (type) {
            case PIG -> new MobModel(type,
                new float[][] {
                    // offsetX, offsetY, offsetZ, sizeX, sizeY, sizeZ
                    {0, 0.4f, 0, 0.7f, 0.6f, 1.0f},      // body
                    {0, 1.0f, 0.35f, 0.6f, 0.6f, 0.6f},  // head
                    {-0.25f, 0, -0.3f, 0.25f, 0.4f, 0.25f}, // leg FL
                    {0.25f, 0, -0.3f, 0.25f, 0.4f, 0.25f},  // leg FR
                    {-0.25f, 0, 0.3f, 0.25f, 0.4f, 0.25f},  // leg BL
                    {0.25f, 0, 0.3f, 0.25f, 0.4f, 0.25f},   // leg BR
                }, 0.9f, 1.6f, 0.91f, 0.72f, 0.72f);

            case COW -> new MobModel(type,
                new float[][] {
                    {0, 0.5f, 0, 0.8f, 0.8f, 1.2f},       // body
                    {0, 1.3f, 0.4f, 0.6f, 0.6f, 0.6f},   // head
                    {-0.3f, 0, -0.4f, 0.3f, 0.5f, 0.3f}, // leg FL
                    {0.3f, 0, -0.4f, 0.3f, 0.5f, 0.3f},  // leg FR
                    {-0.3f, 0, 0.4f, 0.3f, 0.5f, 0.3f},  // leg BL
                    {0.3f, 0, 0.4f, 0.3f, 0.5f, 0.3f},   // leg BR
                }, 1.0f, 1.8f, 0.35f, 0.25f, 0.18f);

            case SHEEP -> new MobModel(type,
                new float[][] {
                    {0, 0.45f, 0, 0.7f, 0.7f, 1.0f},      // body (wool)
                    {0, 1.1f, 0.35f, 0.5f, 0.5f, 0.5f},  // head
                    {-0.25f, 0, -0.3f, 0.25f, 0.45f, 0.25f}, // leg FL
                    {0.25f, 0, -0.3f, 0.25f, 0.45f, 0.25f},  // leg FR
                    {-0.25f, 0, 0.3f, 0.25f, 0.45f, 0.25f},  // leg BL
                    {0.25f, 0, 0.3f, 0.25f, 0.45f, 0.25f},   // leg BR
                }, 0.9f, 1.6f, 0.94f, 0.94f, 0.94f);

            case CHICKEN -> new MobModel(type,
                new float[][] {
                    {0, 0.3f, 0, 0.4f, 0.4f, 0.5f},       // body
                    {0, 0.7f, 0.25f, 0.3f, 0.3f, 0.3f},  // head
                    {-0.1f, 0, 0, 0.15f, 0.3f, 0.15f},   // leg L
                    {0.1f, 0, 0, 0.15f, 0.3f, 0.15f},    // leg R
                }, 0.5f, 1.0f, 1.0f, 1.0f, 1.0f);

            case ZOMBIE -> new MobModel(type,
                new float[][] {
                    {0, 0.9f, 0, 0.6f, 0.9f, 0.3f},       // body
                    {0, 1.8f, 0, 0.5f, 0.5f, 0.5f},      // head
                    {-0.15f, 0, 0, 0.25f, 0.9f, 0.25f},  // leg L
                    {0.15f, 0, 0, 0.25f, 0.9f, 0.25f},   // leg R
                    {-0.4f, 1.5f, 0, 0.2f, 0.9f, 0.2f}, // arm L
                    {0.4f, 1.5f, 0, 0.2f, 0.9f, 0.2f},  // arm R
                }, 0.8f, 2.7f, 0.29f, 0.44f, 0.29f);

            case SKELETON -> new MobModel(type,
                new float[][] {
                    {0, 0.9f, 0, 0.5f, 0.9f, 0.25f},      // body
                    {0, 1.8f, 0, 0.45f, 0.45f, 0.45f},   // head
                    {-0.12f, 0, 0, 0.2f, 0.9f, 0.2f},    // leg L
                    {0.12f, 0, 0, 0.2f, 0.9f, 0.2f},     // leg R
                    {-0.35f, 1.5f, 0, 0.15f, 0.9f, 0.15f}, // arm L
                    {0.35f, 1.5f, 0, 0.15f, 0.9f, 0.15f},  // arm R
                }, 0.7f, 2.7f, 0.82f, 0.82f, 0.82f);

            case CREEPER -> new MobModel(type,
                new float[][] {
                    {0, 0.6f, 0, 0.5f, 1.0f, 0.35f},      // body
                    {0, 1.6f, 0, 0.5f, 0.5f, 0.5f},      // head
                    {-0.18f, 0, -0.15f, 0.25f, 0.6f, 0.25f}, // leg FL
                    {0.18f, 0, -0.15f, 0.25f, 0.6f, 0.25f},  // leg FR
                    {-0.18f, 0, 0.15f, 0.25f, 0.6f, 0.25f},  // leg BL
                    {0.18f, 0, 0.15f, 0.25f, 0.6f, 0.25f},   // leg BR
                }, 0.7f, 2.2f, 0.29f, 0.69f, 0.18f);

            case SPIDER -> new MobModel(type,
                new float[][] {
                    {0, 0.3f, 0, 0.9f, 0.4f, 0.7f},       // body
                    {0, 0.4f, 0.25f, 0.4f, 0.3f, 0.3f},  // head
                    {-0.3f, 0.1f, -0.2f, 0.15f, 0.3f, 0.15f}, // leg FL
                    {0.3f, 0.1f, -0.2f, 0.15f, 0.3f, 0.15f},  // leg FR
                    {-0.3f, 0.1f, 0.2f, 0.15f, 0.3f, 0.15f},  // leg BL
                    {0.3f, 0.1f, 0.2f, 0.15f, 0.3f, 0.15f},   // leg BR
                }, 1.1f, 0.7f, 0.2f, 0.13f, 0.13f);
        };
    }

    public void update(float limbSwing, float limbSwingAmount) {
        this.limbSwing = limbSwing;
        this.limbSwingAmount = limbSwingAmount;
    }

    /**
     * Render the mob model.
     */
    public void render(Matrix4f view, Shader shader, TextureAtlas atlas,
                       com.voxelgame.rendering.model.BlockCube cube,
                       float x, float y, float z, float yaw) {
        Matrix4f baseModel = new Matrix4f();
        baseModel.translate(x, y, z);
        baseModel.rotateY((float) Math.toRadians(yaw));

        float swing = limbSwing * limbSwingAmount;

        // Render each part
        for (int i = 0; i < parts.length; i++) {
            float[] p = parts[i];
            renderPart(baseModel, shader, atlas, cube, p, i, swing);
        }
    }

    private void renderPart(Matrix4f baseModel, Shader shader, TextureAtlas atlas,
                            com.voxelgame.rendering.model.BlockCube cube,
                            float[] part, int partIndex, float swing) {
        Matrix4f model = new Matrix4f(baseModel);

        float ox = part[0], oy = part[1], oz = part[2];
        float sx = part[3], sy = part[4], sz = part[5];

        // Position
        model.translate(ox, oy, oz);

        // Animation for legs (parts 2-5 for 4-legged, 2-3 for 2-legged)
        boolean isLeg = partIndex >= 2 && (parts.length <= 6 || partIndex < 6);
        if (isLeg && swing != 0) {
            // Alternate swing direction for front/back legs
            float dir = (partIndex % 2 == 0) ? 1.0f : -1.0f;
            if (partIndex >= 4) dir *= -1; // Back legs swing opposite
            model.rotateX(swing * 0.5f * dir);
        }

        // Arms swing opposite to legs
        boolean isArm = partIndex >= 4 && parts.length > 6;
        if (isArm && swing != 0) {
            float dir = (partIndex % 2 == 0) ? -1.0f : 1.0f;
            model.rotateX(swing * 0.4f * dir);
        }

        // Scale
        model.scale(sx, sy, sz);

        shader.setUniformMat4("model", model);
        shader.setUniform3f("mobTint", tintR, tintG, tintB);

        // Use a block with appropriate texture
        BlockType block = getBlockForType();
        cube.render(atlas, block, shader);
    }

    private BlockType getBlockForType() {
        // Use different base textures for different mob types
        return switch (type) {
            case PIG -> BlockType.SAND;
            case COW -> BlockType.DIRT;
            case SHEEP -> BlockType.SNOW;
            case CHICKEN -> BlockType.SAND;
            case ZOMBIE -> BlockType.STONE;
            case SKELETON -> BlockType.WHITE_CONCRETE;
            case CREEPER -> BlockType.GRASS_BLOCK;
            case SPIDER -> BlockType.OBSIDIAN;
        };
    }

    public float getWidth() { return width; }
    public float getHeight() { return height; }
}

package com.voxelgame.world.entity;

import org.lwjgl.system.MemoryUtil;

import java.nio.ByteBuffer;

import static org.lwjgl.opengl.GL11.*;
import static org.lwjgl.opengl.GL12.GL_CLAMP_TO_EDGE;

/**
 * Procedurally generates Minecraft-style pixel art textures for mobs.
 * Each texture is 64x64 RGBA and features different regions for each body part.
 */
public class MobTextures {

    public static final int TEX_SIZE = 64;

    // Texture IDs for each mob
    public static int pigTexture;
    public static int cowTexture;
    public static int sheepTexture;
    public static int chickenTexture;
    public static int zombieTexture;
    public static int skeletonTexture;
    public static int creeperTexture;
    public static int spiderTexture;

    /**
     * Generate all mob textures and upload to GPU.
     */
    public static void generateAll() {
        pigTexture = generateTexture(MobTextureGenerator::pig);
        cowTexture = generateTexture(MobTextureGenerator::cow);
        sheepTexture = generateTexture(MobTextureGenerator::sheep);
        chickenTexture = generateTexture(MobTextureGenerator::chicken);
        zombieTexture = generateTexture(MobTextureGenerator::zombie);
        skeletonTexture = generateTexture(MobTextureGenerator::skeleton);
        creeperTexture = generateTexture(MobTextureGenerator::creeper);
        spiderTexture = generateTexture(MobTextureGenerator::spider);
    }

    /**
     * Get the texture ID for a mob type.
     */
    public static int getTexture(MobModel.MobType type) {
        return switch (type) {
            case PIG -> pigTexture;
            case COW -> cowTexture;
            case SHEEP -> sheepTexture;
            case CHICKEN -> chickenTexture;
            case ZOMBIE -> zombieTexture;
            case SKELETON -> skeletonTexture;
            case CREEPER -> creeperTexture;
            case SPIDER -> spiderTexture;
        };
    }

    private static int generateTexture(TextureGenerator generator) {
        int[] pixels = new int[TEX_SIZE * TEX_SIZE];
        generator.generate(pixels, TEX_SIZE);

        ByteBuffer buf = MemoryUtil.memAlloc(TEX_SIZE * TEX_SIZE * 4);
        for (int p : pixels) {
            buf.put((byte) ((p >> 16) & 0xFF)); // R
            buf.put((byte) ((p >> 8) & 0xFF));  // G
            buf.put((byte) (p & 0xFF));         // B
            buf.put((byte) ((p >>> 24) & 0xFF)); // A
        }
        buf.flip();

        int id = glGenTextures();
        glBindTexture(GL_TEXTURE_2D, id);
        glTexImage2D(GL_TEXTURE_2D, 0, GL_RGBA, TEX_SIZE, TEX_SIZE, 0,
            GL_RGBA, GL_UNSIGNED_BYTE, buf);
        glTexParameteri(GL_TEXTURE_2D, GL_TEXTURE_MIN_FILTER, GL_NEAREST);
        glTexParameteri(GL_TEXTURE_2D, GL_TEXTURE_MAG_FILTER, GL_NEAREST);
        glTexParameteri(GL_TEXTURE_2D, GL_TEXTURE_WRAP_S, GL_CLAMP_TO_EDGE);
        glTexParameteri(GL_TEXTURE_2D, GL_TEXTURE_WRAP_T, GL_CLAMP_TO_EDGE);
        glBindTexture(GL_TEXTURE_2D, 0);

        MemoryUtil.memFree(buf);
        return id;
    }

    @FunctionalInterface
    private interface TextureGenerator {
        void generate(int[] pixels, int size);
    }

    public static void cleanup() {
        glDeleteTextures(new int[]{
            pigTexture, cowTexture, sheepTexture, chickenTexture,
            zombieTexture, skeletonTexture, creeperTexture, spiderTexture
        });
    }
}

package com.voxelgame.world.entity;

/**
 * Generates pixel-art textures for each mob in Minecraft style.
 * Each texture is 64x64 with specific UV regions for body parts.
 *
 * UV Layout (Minecraft-style):
 * - Head: 0-16 x 0-16 (top-left)
 * - Body: 16-32 x 16-32
 * - Legs: 0-16 x 32-48
 * - Arms: 40-56 x 16-32
 */
public class MobTextureGenerator {

    // Helper: set pixel with bounds check
    private static void px(int[] pixels, int size, int x, int y, int color) {
        if (x < 0 || y < 0 || x >= size || y >= size) return;
        pixels[y * size + x] = color;
    }

    // Helper: fill rectangle
    private static void fill(int[] pixels, int size, int x, int y, int w, int h, int color) {
        for (int dy = 0; dy < h; dy++) {
            for (int dx = 0; dx < w; dx++) {
                px(pixels, size, x + dx, y + dy, color);
            }
        }
    }

    // Helper: draw outline
    private static void outline(int[] pixels, int size, int x, int y, int w, int h, int color) {
        for (int dx = 0; dx < w; dx++) {
            px(pixels, size, x + dx, y, color);
            px(pixels, size, x + dx, y + h - 1, color);
        }
        for (int dy = 0; dy < h; dy++) {
            px(pixels, size, x, y + dy, color);
            px(pixels, size, x + w - 1, y + dy, color);
        }
    }

    /**
     * PIG TEXTURE (64x64)
     * Pink snout, ears, cute face
     */
    static void pig(int[] pixels, int size) {
        // Fill transparent
        java.util.Arrays.fill(pixels, 0x00000000);

        // Head (8-24, 8-24) - pink
        fill(pixels, size, 8, 8, 16, 16, 0xFFF0A0A0);
        // Snout (12-20, 20-24) - darker pink
        fill(pixels, size, 12, 20, 8, 4, 0xFFE09090);
        // Nostrils
        px(pixels, size, 14, 21, 0xFF806060);
        px(pixels, size, 17, 21, 0xFF806060);
        // Eyes
        px(pixels, size, 10, 12, 0xFF303030);
        px(pixels, size, 18, 12, 0xFF303030);

        // Body (24-40, 16-32) - pink
        fill(pixels, size, 24, 16, 16, 16, 0xFFF0A0A0);

        // Legs (4-8, 32-48) - pink
        fill(pixels, size, 4, 32, 4, 16, 0xFFE89898);
        fill(pixels, size, 8, 32, 4, 16, 0xFFE89898);
        fill(pixels, size, 12, 32, 4, 16, 0xFFE89898);
        fill(pixels, size, 16, 32, 4, 16, 0xFFE89898);

        // Ears on head
        fill(pixels, size, 8, 4, 4, 4, 0xFFE09090);
        fill(pixels, size, 20, 4, 4, 4, 0xFFE09090);
    }

    /**
     * COW TEXTURE (64x64)
     * Brown body with black/white patches
     */
    static void cow(int[] pixels, int size) {
        java.util.Arrays.fill(pixels, 0x00000000);

        // Head - brown
        fill(pixels, size, 8, 8, 16, 16, 0xFF6B4A30);
        // Horns
        fill(pixels, size, 8, 4, 3, 4, 0xFFE8E0D0);
        fill(pixels, size, 21, 4, 3, 4, 0xFFE8E0D0);
        // Muzzle - lighter
        fill(pixels, size, 12, 18, 8, 6, 0xFFD0B8A0);
        // Eyes
        px(pixels, size, 10, 12, 0xFF202020);
        px(pixels, size, 18, 12, 0xFF202020);

        // Body - brown with white patches
        fill(pixels, size, 24, 16, 20, 16, 0xFF6B4A30);
        // White patch on belly
        fill(pixels, size, 28, 20, 12, 10, 0xFFF0F0F0);
        // Black patch
        fill(pixels, size, 32, 16, 8, 8, 0xFF3A3A3A);

        // Legs - brown
        fill(pixels, size, 4, 32, 5, 16, 0xFF5A3A20);
        fill(pixels, size, 10, 32, 5, 16, 0xFF5A3A20);
        fill(pixels, size, 16, 32, 5, 16, 0xFF5A3A20);
        fill(pixels, size, 22, 32, 5, 16, 0xFF5A3A20);
    }

    /**
     * SHEEP TEXTURE (64x64)
     * White fluffy wool, gray face
     */
    static void sheep(int[] pixels, int size) {
        java.util.Arrays.fill(pixels, 0x00000000);

        // Head - gray
        fill(pixels, size, 8, 8, 16, 16, 0xFFD8D8D8);
        // Eyes
        px(pixels, size, 10, 12, 0xFF202020);
        px(pixels, size, 18, 12, 0xFF202020);
        // Nose
        fill(pixels, size, 14, 16, 4, 3, 0xFFC0B0B0);

        // Body - fluffy white wool
        fill(pixels, size, 24, 16, 20, 16, 0xFFF5F5F5);
        // Wool texture - slight variations
        for (int y = 16; y < 32; y += 3) {
            for (int x = 24; x < 44; x += 3) {
                px(pixels, size, x, y, 0xFFEBEBEB);
            }
        }

        // Legs - gray
        fill(pixels, size, 4, 32, 5, 16, 0xFFC8C8C8);
        fill(pixels, size, 10, 32, 5, 16, 0xFFC8C8C8);
        fill(pixels, size, 16, 32, 5, 16, 0xFFC8C8C8);
        fill(pixels, size, 22, 32, 5, 16, 0xFFC8C8C8);
    }

    /**
     * CHICKEN TEXTURE (64x64)
     * White body, red comb, yellow beak
     */
    static void chicken(int[] pixels, int size) {
        java.util.Arrays.fill(pixels, 0x00000000);

        // Head - white
        fill(pixels, size, 8, 8, 12, 12, 0xFFFAFAFA);
        // Comb (red thing on top)
        fill(pixels, size, 10, 4, 6, 4, 0xFFE03030);
        // Beak
        fill(pixels, size, 18, 12, 4, 3, 0xFFF0C020);
        // Wattle
