package com.voxelgame.world.entity;

import com.voxelgame.rendering.Shader;
import org.lwjgl.system.MemoryUtil;

import java.nio.FloatBuffer;

import static org.lwjgl.opengl.GL11.*;
import static org.lwjgl.opengl.GL15.*;
import static org.lwjgl.opengl.GL20.*;
import static org.lwjgl.opengl.GL30.*;

/**
 * A textured box mesh for mob body parts. Uses custom UV coordinates
 * to map different regions of the mob texture atlas to each face.
 */
public class MobMesh {

    /** floats per vertex: x, y, z, u, v, shade, r, g, b */
    private static final int VERTEX_SIZE = 9;

    private final int vao;
    private final int vbo;

    public MobMesh() {
        vao = glGenVertexArrays();
        glBindVertexArray(vao);

        vbo = glGenBuffers();
        glBindBuffer(GL_BUFFER_BUFFER, vbo);

        int stride = VERTEX_SIZE * Float.BYTES;
        glVertexAttribPointer(0, 3, GL_FLOAT, false, stride, 0);
        glEnableVertexAttribArray(0);
        glVertexAttribPointer(1, 2, GL_FLOAT, false, stride, 3 * Float.BYTES);
        glEnableVertexAttribArray(1);
        glVertexAttribPointer(2, 1, GL_FLOAT, false, stride, 5 * Float.BYTES);
        glEnableVertexAttribArray(2);
        glVertexAttribPointer(3, 3, GL_FLOAT, false, stride, 6 * Float.BYTES);
        glEnableVertexAttribArray(3);

        glBindVertexArray(0);
    }

    /**
     * Build a box mesh with specific UV region for a body part.
     *
     * @param u, v - top-left corner of UV region in texture
     * @param w, h - size of UV region
     * @param uMax, vMax - texture dimensions
     */
    public void buildBox(float ox, float oy, float oz, float sx, float sy, float sz,
                        float u, float v, float w, float h, float uMax, float vMax) {
        // Calculate UV coordinates for each face
        float u1 = u / uMax;
        float v1 = v / vMax;
        float u2 = (u + w) / uMax;
        float v2 = (v + h) / vMax;

        // Generate vertices for 6 faces
        FloatBuffer buf = MemoryUtil.memAllocFloat(36 * VERTEX_SIZE);

        // Front face (+Z)
        addQuad(buf,
            ox, oy, oz + sz,  ox + sx, oy, oz + sz,
            ox + sx, oy + sy, oz + sz,  ox, oy + sy, oz + sz,
            u1, v1, u2, v2, 0.8f);

        // Back face (-Z)
        addQuad(buf,
            ox + sx, oy, oz,  ox, oy, oz,
            ox, oy + sy, oz,  ox + sx, oy + sy, oz,
            u1, v1, u2, v2, 0.7f);

        // Top face (+Y)
        addQuad(buf,
            ox, oy + sy, oz + sz,  ox + sx, oy + sy, oz + sz,
            ox + sx, oy + sy, oz,  ox, oy + sy, oz,
            u1, v1, u2, v2, 1.0f);

        // Bottom face (-Y)
        addQuad(buf,
            ox, oy, oz,  ox + sx, oy, oz,
            ox + sx, oy, oz + sz,  ox, oy, oz + sz,
            u1, v1, u2, v2, 0.5f);

        // Right face (+X)
        addQuad(buf,
            ox + sx, oy, oz + sz,  ox + sx, oy, oz,
            ox + sx, oy + sy, oz,  ox + sx, oy + sy, oz + sz,
            u1, v1, u2, v2, 0.7f);

        // Left face (-X)
        addQuad(buf,
            ox, oy, oz,  ox, oy, oz + sz,
            ox, oy + sy, oz + sz,  ox, oy + sy, oz,
            u1, v1, u2, v2, 0.6f);

        buf.flip();

        glBindBuffer(GL_ARRAY_BUFFER, vbo);
        glBufferData(GL_ARRAY_BUFFER, buf, GL_DYNAMIC_DRAW);
        MemoryUtil.memFree(buf);
    }

    private void addQuad(FloatBuffer b,
                         float x1, float y1, float z1,
                         float x2, float y2, float z2,
                         float x3, float y3, float z3,
                         float x4, float y4, float z4,
                         float u1, float v1, float u2, float v2, float shade) {
        // Triangle 1
        b.put(x1).put(y1).put(z1).put(u1).put(v1).put(shade).put(1).put(1).put(1);
        b.put(x2).put(y2).put(z2).put(u2).put(v1).put(shade).put(1).put(1).put(1);
        b.put(x3).put(y3).put(z3).put(u2).put(v2).put(shade).put(1).put(1).put(1);
        // Triangle 2
        b.put(x1).put(y1).put(z1).put(u1).put(v1).put(shade).put(1).put(1).put(1);
        b.put(x3).put(y3).put(z3).put(u2).put(v2).put(shade).put(1).put(1).put(1);
        b.put(x4).put(y4).put(z4).put(u1).put(v2).put(shade).put(1).put(1).put(1);
    }

    public void render() {
        glBindVertexArray(vao);
        glDrawArrays(GL_TRIANGLES, 0, 36);
        glBindVertexArray(0);
    }

    public void cleanup() {
        glDeleteBuffers(vbo);
        glDeleteVertexArrays(vao);
    }
}

#version 330 core

layout (location = 0) in vec3 aPos;
layout (location = 1) in vec2 aTexCoord;
layout (location = 2) in float aShade;
layout (location = 3) in vec3 aColor;

uniform mat4 model;
uniform mat4 view;
uniform mat4 projection;

out vec2 TexCoord;
out vec3 VertexColor;
out float Shade;

void main() {
    gl_Position = projection * view * model * vec4(aPos, 1.0);
    TexCoord = aTexCoord;
    VertexColor = aColor;
    Shade = aShade;
}

#version 330 core

in vec2 TexCoord;
in vec3 VertexColor;
in float Shade;

uniform sampler2D mobTexture;
uniform vec3 tint;

out vec4 FragColor;

void main() {
    vec4 tex = texture(mobTexture, TexCoord);
    if (tex.a < 0.1) discard;

    vec3 color = tex.rgb * VertexColor * Shade * tint;
    FragColor = vec4(color, tex.a);
}

package com.voxelgame.world.entity;

