/**
 * Minecraft-style mob model with proper textures and animations.
 */
public class MobModel {

    public enum MobType {
        PIG, COW, SHEEP, CHICKEN, ZOMBIE, SKELETON, CREEPER, SPIDER
    }

    private final MobType type;

    // UV coordinates for each body part (in 64x64 texture)
    // Format: (u, v, width, height)
    private final int[][] partUVs;

    // Part definitions: offsetX, offsetY, offsetZ, sizeX, sizeY, sizeZ
    private final float[][] parts;

    // Color tint
    private final float tintR, tintG, tintB;

    // Dimensions
    public final float width;
    public final float height;

    // Animation
    private float limbSwing = 0;
    private float limbSwingAmount = 0;

    private MobModel(MobType type, float[][] parts, int[][] uvs,
                     float w, float h, float tr, float tg, float tb) {
        this.type = type;
        this.parts = parts;
        this.partUVs = uvs;
        this.width = w;
        this.height = h;
        this.tintR = tr; this.tintG = tg; this.tintB = tb;
