                    {0, 1.8f, 0, 0.45f, 0.45f, 0.45f},       // head
                    {0, 0.9f, 0, 0.5f, 0.9f, 0.25f},          // body
                    {-0.12f, 0, 0, 0.2f, 0.9f, 0.2f},        // leg L
                    {0.12f, 0, 0, 0.2f, 0.9f, 0.2f},         // leg R
