        float r, g, b;       // color

        Part(float ox, float oy, float oz, float sx, float sy, float sz,
             float r, float g, float b) {
            this.ox = ox; this.oy = oy; this.oz = oz;
            this.sx = sx; this.sy = sy; this.sz = sz;
