/**
 * Minecraft-style mob model with colored parts.
 */
public class MobModel {

    public enum MobType {
        PIG, COW, SHEEP, CHICKEN, ZOMBIE, SKELETON, CREEPER, SPIDER
    }

    private static class Part {
        float ox, oy, oz;
        float sx, sy, sz;
        float r, g, b;

        Part(float ox, float oy, float oz, float sx, float sy, float sz,
             float r, float g, float b) {
            this.ox = ox; this.oy = oy; this.oz = oz;
            this.sx = sx; this.sy = sy; this.sz = sz;
            this.r = r; this.g = g; this.b = b;
        }
    }

    private final MobType type;
    private final Part[] parts;
    public final float width;
    public final float height;

    private MobModel(MobType type, Part[] parts, float w, float h) {
        this.type = type;
        this.parts = parts;
        this.width = w;
        this.height = h;
    }

    public static MobModel create(MobType type) {
