                new Part(0.22f, 0, -0.25f, 0.22f, 0.4f, 0.22f, 0.9f, 0.7f, 0.7f), // leg FR
                new Part(-0.22f, 0, 0.25f, 0.22f, 0.4f, 0.22f, 0.9f, 0.7f, 0.7f), // leg BL
                new Part(0.22f, 0, 0.25f, 0.22f, 0.4f, 0.22f, 0.9f, 0.7f, 0.7f), // leg BR
