                new Part(-0.15f, 0, 0, 0.25f, 0.9f, 0.25f, 0.19f, 0.19f, 0.31f), // leg L
                new Part(0.15f, 0, 0, 0.25f, 0.9f, 0.25f, 0.19f, 0.19f, 0.31f), // leg R
            }, 0.8f, 2.7f);

