package com.voxelgame.render;

import org.lwjgl.system.MemoryUtil;

import java.io.IOException;
import java.nio.ByteBuffer;
import java.nio.file.Files;
import java.nio.file.Paths;

import static org.lwjgl.opengl.GL11.*;
import static org.lwjgl.opengl.GL12.GL_CLAMP_TO_EDGE;
import static org.lwjgl.stb.STBImage.stbi_load_from_memory;

/**
 * Loads a PNG texture from disk with pixel-art settings: GL_NEAREST filtering,
 * no mipmaps, CLAMP_TO_EDGE wrapping.
 */
public class TextureLoader {

    public static int loadTexture(String path) {
        byte[] imageData;
        try {
            imageData = Files.readAllBytes(Paths.get(path));
        } catch (IOException e) {
            System.err.println("TextureLoader: cannot read " + path + " - " + e.getMessage());
            return 0;
        }

        ByteBuffer buf = MemoryUtil.memAlloc(imageData.length).put(imageData).flip();
        int[] w = new int[1], h = new int[1], channels = new int[1];
        ByteBuffer image = stbi_load_from_memory(buf, w, h, channels, 4);
        MemoryUtil.memFree(buf);

        if (image == null) {
            System.err.println("TextureLoader: STB failed to decode " + path);
            return 0;
        }

        int id = glGenTextures();
        glBindTexture(GL_TEXTURE_2D, id);
        glTexImage2D(GL_TEXTURE_2D, 0, GL_RGBA, w[0], h[0], 0, GL_RGBA, GL_UNSIGNED_BYTE, image);
        glTexParameteri(GL_TEXTURE_2D, GL_TEXTURE_MIN_FILTER, GL_NEAREST);
        glTexParameteri(GL_TEXTURE_2D, GL_TEXTURE_MAG_FILTER, GL_NEAREST);
        glTexParameteri(GL_TEXTURE_2D, GL_TEXTURE_WRAP_S, GL_CLAMP_TO_EDGE);
        glTexParameteri(GL_TEXTURE_2D, GL_TEXTURE_WRAP_T, GL_CLAMP_TO_EDGE);
        glBindTexture(GL_TEXTURE_2D, 0);

        org.lwjgl.stb.STBImage.stbi_image_free(image);
        return id;
    }
}

package com.voxelgame.world.entity;

import com.voxelgame.rendering.Shader;
import com.voxelgame.rendering.model.ModelBox;
import org.joml.Matrix4f;

/**
 * Zoloy (Пепельный прислужник) — part-based mob model with pivots and base rotations.
 *
 * The model is built in skin-pixel space where 16px = 1 block. The whole model
 * is scaled by 0.8 on the entity, giving a height of roughly 1.6 blocks.
 * Each part rotates about its own pivot (shoulder, hip, neck...) and carries
 * a base rotation that gives the mob its hunched posture.
 */
public class ZoloyModel {

    // --- Boxes (texture u, v, width, height, depth) ---
    private final ModelBox head;
    private final ModelBox body;
    private final ModelBox rarm;
    private final ModelBox larm;
    private final ModelBox rleg;
    private final ModelBox lleg;
    private final ModelBox cloak;

    // --- Pivot points (in blocks, relative to model origin at feet) ---
    private static final float[] PIVOT_HEAD   = {0.0f, 1.5f, 0.0f};
    private static final float[] PIVOT_BODY   = {0.0f, 1.5f, 0.0f};
    private static final float[] PIVOT_RARM   = {-0.375f, 1.45f, 0.0f};
    private static final float[] PIVOT_LARM   = {0.375f, 1.45f, 0.0f};
    private static final float[] PIVOT_RLEG   = {-0.125f, 0.75f, 0.0f};
    private static final float[] PIVOT_LLEG   = {0.125f, 0.75f, 0.0f};
    private static final float[] PIVOT_CLOAK  = {0.0f, 1.125f, -0.16f};

    // --- Base rotations (radians, posture) ---
    private static final float BASE_ROT_BODY  = 0.35f;
    private static final float BASE_ROT_RARM  = 0.25f;
    private static final float BASE_ROT_LARM  = 0.25f;
    private static final float BASE_ROT_HEAD  = -0.15f;

    // Scratch matrices so render() allocates nothing
    private final Matrix4f scratch = new Matrix4f();

    public ZoloyModel() {
        head  = new ModelBox(0, 0, 8, 8, 8, -4, 12, -4);
        body  = new ModelBox(16, 16, 8, 12, 4, -4, 0, -2);
        rarm  = new ModelBox(40, 16, 4, 12, 4, -4, 0, -2);
        larm  = new ModelBox(32, 48, 4, 12, 4, 0, 0, -2);
        rleg  = new ModelBox(0, 16, 4, 12, 4, -4, 0, -2);
        lleg  = new ModelBox(16, 48, 4, 12, 4, 0, 0, -2);
        cloak = new ModelBox(16, 28, 8, 12, 4, -4, 0, -2, 0.02f);
    }

    /**
     * Render one part: mvp = viewProj * base * translate(pivot) * rotateX(rotX).
     *
     * @param part   the box to draw
     * @param pivot  pivot point in model space
     * @param rotX   total rotation about X (base + animation)
     * @param base   the entity's base model matrix (already includes translate/rotateY/scale)
     * @param viewProj  projection * view from the camera
     * @param shader    active shader (uniforms already bound)
     */
    private void renderPart(ModelBox part, float[] pivot, float rotX,
                            Matrix4f base, Matrix4f viewProj, Shader shader) {
        scratch.identity();
        scratch.translate(pivot[0], pivot[1], pivot[2]);
        scratch.rotateX(rotX);
        scratch.translate(-pivot[0], -pivot[1], -pivot[2]);

        Matrix4f mvp = viewProj.mul(base, new Matrix4f()).mul(scratch);
        shader.setUniformMat4("model", mvp);
        part.render();
    }

    /**
     * @param base     entity base matrix (translate(pos) * rotateY(yaw) * scale(0.8))
     * @param viewProj projection * view
     * @param shader   active shader with uniforms bound
     * @param walkPhase  current walking phase for limb swing
     * @param attackPhase 0..1 attack swing, 0 = idle
     */
    public void render(Matrix4f base, Matrix4f viewProj, Shader shader,
                       float walkPhase, float attackPhase) {

        float swing = (float) Math.sin(walkPhase) * 0.6f;

        // Legs in counter-phase
        renderPart(rleg, PIVOT_RLEG, swing, base, viewProj, shader);
        renderPart(lleg, PIVOT_LLEG, -swing, base, viewProj, shader);

        // Body with hunch
        renderPart(body, PIVOT_BODY, BASE_ROT_BODY, base, viewProj, shader);

        // Cloak behind body — no swing, slight extra tilt
        renderPart(cloak, PIVOT_CLOAK, BASE_ROT_BODY * 0.5f, base, viewProj, shader);

        // Arms: base + walk counter-phase + attack swing on right arm
        float rarmRot = BASE_ROT_RARM - swing;
        if (attackPhase > 0f) {
            // attack swing: rotX goes from -2.2 to +0.6
            float t = attackPhase;
            float arc = (float) Math.sin(t * Math.PI);
            rarmRot = -2.2f + 2.8f * arc;
        }
        renderPart(rarm, PIVOT_RARM, rarmRot, base, viewProj, shader);
        renderPart(larm, PIVOT_LARM, BASE_ROT_LARM + swing, base, viewProj, shader);

        // Head
        renderPart(head, PIVOT_HEAD, BASE_ROT_HEAD, base, viewProj, shader);
    }

    public void cleanup() {
        head.cleanup();
        body.cleanup();
        rarm.cleanup();
        larm.cleanup();
        rleg.cleanup();
        lleg.cleanup();
        cloak.cleanup();
    }
}

package com.voxelgame.world.entity;

import com.voxelgame.player.Player;
import com.voxelgame.world.World;
import org.joml.Vector3f;

/**
 * Zoloy (Пепельный прислужник) — hostile mob with patrol/chase/attack AI.
 *
 * States: PATROL (wander to random point) → CHASE (pursue player within 16 blocks)
 * → ATTACK (strike within 1.5 blocks). Aggro hysteresis: de-aggros at >24 blocks.
 * HP = 30, damage = 4, attack cooldown = 1.2s.
 */
public class Zoloy {

    public enum State { PATROL, CHASE, ATTACK }

    // Stats
    private static final float MAX_HP = 30.0f;
    private static final float DAMAGE = 4.0f;
    private static final float ATTACK_COOLDOWN = 1.2f;
    private static final float ATTACK_DURATION = 0.3f;

    // Movement
    private static final float PATROL_SPEED = 1.2f;
    private static final float CHASE_SPEED = 2.3f;
    private static final float GRAVITY = 28.0f;

    // AI ranges
    private static final float AGGRO_RANGE = 16.0f;
    private static final float DEAGGRO_RANGE = 24.0f;
    private static final float ATTACK_RANGE = 1.5f;

    private final World world;
    private final Vector3f position;
    private final Vector3f velocity = new Vector3f();
    private float yaw;

    private float hp = MAX_HP;
    private boolean dead = false;
    private State state = State.PATROL;

    // Animation
    private float walkPhase = 0;
    private float attackTimer = 0;       // counts up during attack
    private float attackCooldown = 0;    // counts down after attack
    private float limbSwingAmount = 0;

    // Patrol target
    private final Vector3f patrolTarget = new Vector3f();
    private float patrolRetargetTimer = 0;
    private boolean hasPatrolTarget = false;

    public Zoloy(World world, float x, float y, float z) {
        this.world = world;
        this.position = new Vector3f(x, y, z);
        this.yaw = (float) (Math.random() * Math.PI * 2);
    }

    public void update(float dt, Player player) {
        if (dead) return;

        if (attackCooldown > 0) attackCooldown -= dt;

        Vector3f playerPos = player.getPosition();
        float dx = playerPos.x - position.x;
        float dz = playerPos.z - position.z;
        float distToPlayer = (float) Math.sqrt(dx * dx + dz * dz);

        // --- State machine with hysteresis ---
        switch (state) {
            case PATROL:
                if (distToPlayer < AGGRO_RANGE) {
                    state = State.CHASE;
                }
                break;
            case CHASE:
                if (distToPlayer < ATTACK_RANGE && attackCooldown <= 0) {
                    state = State.ATTACK;
                    attackTimer = 0;
                } else if (distToPlayer > DEAGGRO_RANGE) {
                    state = State.PATROL;
                    hasPatrolTarget = false;
                }
                break;
            case ATTACK:
                attackTimer += dt;
                if (attackTimer >= ATTACK_DURATION) {
                    // Deal damage
                    if (distToPlayer < ATTACK_RANGE + 0.5f) {
                        player.applyDamage(DAMAGE);
                    }
                    attackCooldown = ATTACK_COOLDOWN;
                    state = State.CHASE;
                }
                break;
        }

        // --- Movement ---
        switch (state) {
            case PATROL:
                updatePatrol(dt);
                break;
            case CHASE:
            case ATTACK:
                // Face and move toward player
                yaw = (float) Math.atan2(dx, dz);
                if (state == State.CHASE && distToPlayer > ATTACK_RANGE * 0.8f) {
                    moveToward(playerPos, CHASE_SPEED, dt);
                } else if (state == State.PATROL) {
                    moveToward(playerPos, CHASE_SPEED, dt);
                }
                break;
        }

        // --- Physics (gravity + collision) ---
        applyPhysics(dt);

        // --- Animation ---
        float speed = (float) Math.sqrt(velocity.x * velocity.x + velocity.z * velocity.z);
        walkPhase += dt * (7.0f + speed * 2.0f);
        limbSwingAmount = Math.min(speed / CHASE_SPEED, 1.0f);
    }

    private void updatePatrol(float dt) {
        patrolRetargetTimer -= dt;
        if (!hasPatrolTarget || patrolRetargetTimer <= 0) {
            // Pick a random point within ~8 blocks
            float angle = (float) (Math.random() * Math.PI * 2);
            float dist = 3.0f + (float) Math.random() * 5.0f;
            patrolTarget.set(
                position.x + (float) Math.cos(angle) * dist,
                position.y,
                position.z + (float) Math.sin(angle) * dist
            );
            hasPatrolTarget = true;
            patrolRetargetTimer = 3.0f + (float) Math.random() * 4.0f;
        }

        float tx = patrolTarget.x - position.x;
        float tz = patrolTarget.z - patrolTarget.z;
        float dist = (float) Math.sqrt(tx * tx + tz * tz);
        if (dist > 0.5f) {
            yaw = (float) Math.atan2(tx, tz);
            moveToward(patrolTarget, PATROL_SPEED, dt);
        } else {
            hasPatrolTarget = false;
        }
    }

    private void moveToward(Vector3f target, float speed, float dt) {
        float dx = target.x - position.x;
        float dz = target.z - position.z;
        float len = (float) Math.sqrt(dx * dx + dz * dz);
        if (len < 0.01f) return;
        velocity.x = (dx / len) * speed;
        velocity.z = (dz / len) * speed;
    }

    private void applyPhysics(float dt) {
        velocity.y -= GRAVITY * dt;
        if (velocity.y < -78.4f) velocity.y = -78.4f;

        // Move with simple ground collision
        position.x += velocity.x * dt;
        position.z += velocity.z * dt;

        position.y += velocity.y * dt;
        int groundY = world.getGroundHeight((int) position.x, (int) position.z);
        if (position.y < groundY + 0.01f) {
            position.y = groundY;
            velocity.y = 0;
        }
    }

    public float getAttackPhase() {
        if (state == State.ATTACK) {
            return Math.min(attackTimer / ATTACK_DURATION, 1.0f);
        }
        return 0;
    }

    // --- Getters ---
    public Vector3f getPosition() { return position; }
    public float getYaw() { return yaw; }
    public float getWalkPhase() { return walkPhase; }
    public float getLimbSwingAmount() { return limbSwingAmount; }
    public float getHp() { return hp; }
    public float getMaxHp() { return MAX_HP; }
    public boolean isDead() { return dead; }
    public State getState() { return state; }

    public void takeDamage(float dmg) {
        hp -= dmg;
        if (hp <= 0) {
            hp = 0;
            dead = true;
        }
    }
}

