package com.voxelgame.render;

import com.voxelgame.rendering.Camera;
import com.voxelgame.rendering.Shader;
import com.voxelgame.world.entity.Zoloy;
import com.voxelgame.world.entity.ZoloyModel;
import org.joml.Matrix4f;
import org.joml.Vector3f;

import java.util.List;

import static org.lwjgl.opengl.GL11.*;
import static org.lwjgl.opengl.GL13.*;

/**
 * Renders Zoloy mobs using the part-based model and a dedicated texture.
 * Each mob is drawn with its own model matrix: translate(pos) * rotateY(yaw) * scale(0.8).
 */
public class MobRenderer {

    private final Shader shader;
    private final int textureId;
    private final ZoloyModel model;

    // Scratch matrices
    private final Matrix4f baseMatrix = new Matrix4f();
    private final Matrix4f viewProj = new Matrix4f();

    public MobRenderer() {
        shader = new Shader("shaders/model.vert", "shaders/model.frag");
        textureId = TextureLoader.loadTexture("src/main/resources/textures/entities/zoloy.png");
        model = new ZoloyModel();
    }

    public void render(List<Zoloy> mobs, Camera camera) {
        if (mobs.isEmpty()) return;

        glEnable(GL_DEPTH_TEST);
        glEnable(GL_CULL_FACE);
        glCullFace(GL_BACK);
        glFrontFace(GL_CCW);
        glDisable(GL_BLEND);

        shader.bind();
        shader.setUniformMat4("projection", camera.getProjectionMatrix());
        shader.setUniformMat4("view", camera.getViewMatrix());
        shader.setUniform1i("skin", 0);
        shader.setUniform1f("lightLevel", 1.0f);
        shader.setUniform3f("sunColor", new Vector3f(1.0f, 1.0f, 1.0f));

        glActiveTexture(GL_TEXTURE0);
        glBindTexture(GL_TEXTURE_2D, textureId);

        viewProj.set(camera.getProjectionMatrix()).mul(camera.getViewMatrix());

        for (Zoloy mob : mobs) {
            Vector3f pos = mob.getPosition();
            baseMatrix.identity();
            baseMatrix.translate(pos.x, pos.y, pos.z);
            baseMatrix.rotateY(mob.getYaw());
            baseMatrix.scale(0.8f);

            model.render(baseMatrix, viewProj, shader, mob.getWalkPhase(), mob.getAttackPhase());
        }

        shader.unbind();
    }

    public void cleanup() {
        model.cleanup();
        shader.cleanup();
        glDeleteTextures(textureId);
    }
}

