/**
 * Parse and execute a chat command. Returns true if recognized.
 */
private boolean handleCommand(String cmd) {
    cmd = cmd.trim();
    if (!cmd.startsWith("/")) return false;
    String[] parts = cmd.substring(1).split("\\s+");
    if (parts.length == 0) return false;

    switch (parts[0].toLowerCase()) {
        case "spawn":
            if (parts.length >= 2 && parts[1].equalsIgnoreCase("zoloy")) {
                spawnZoloy();
                System.out.println("Spawned Zoloy at player position");
                return true;
            }
            break;
        case "help":
            System.out.println("Commands: /spawn zoloy");
            return true;
    }
    return false;
}

/** Spawn a Zoloy mob 5 blocks in front of the player. */
private void spawnZoloy() {
    if (world == null || player == null) return;
    Vector3f pos = player.getPosition();
    org.joml.Vector3f front = camera.getFront();
    float sx = pos.x + front.x * 5.0f;
    float sz = pos.z + front.z * 5.0f;
    int groundY = world.getGroundHeight((int) sx, (int) sz);
    world.getMobs().add(new com.voxelgame.world.entity.Zoloy(
        world, sx, groundY + 0.01f, sz));
}

