 * Spec verification:
 *   head: 8x8x8, box(-4,-8,-4)-(4,0,4),   pivot(0,0,0)   — OK
 *   body: 8x12x4, box(-4,0,-2)-(4,12,2),   pivot(0,0,0)   — OK
 *   rArm: 4x12x4, box(-2,-2,-2)-(2,10,2),  pivot(-5,2,0)  — OK
 *   lArm: 4x12x4, box(-2,-2,-2)-(2,10,2),  pivot(5,2,0)   — OK
 *   rLeg: 4x12x4, box(-2,0,-2)-(2,12,2),   pivot(-1.9,12,0) — OK
 *   lLeg: 4x12x4, box(-2,0,-2)-(2,12,2),   pivot(1.9,12,0)  — OK
 *   cloak: 8x12x4, overlay, expanded 0.5px, pivot(0,2,0) — OK
 */
public class ZoloyModel {

    // Parts
    private final ModelBox head;
    private final ModelBox body;
    private final ModelBox rarm;
    private final ModelBox larm;
    private final ModelBox rleg;
    private final ModelBox lleg;
    private final ModelBox cloak;

    // Pivots relative to neck (in pixels, Y down)
    private static final float[] PIVOT_HEAD  = {0, 0, 0};
    private static final float[] PIVOT_BODY  = {0, 0, 0};
    private static final float[] PIVOT_RARM  = {-5, 2, 0};
    private static final float[] PIVOT_LARM  = {5, 2, 0};
    private static final float[] PIVOT_RLEG  = {-1.9f, 12, 0};
    private static final float[] PIVOT_LLEG  = {1.9f, 12, 0};
    private static final float[] PIVOT_CLOAK = {0, 2, 0};

    // Base posture
    private static final float BASE_BODY  = 0.35f;
    private static final float BASE_RARM  = 0.25f;
    private static final float BASE_LARM  = 0.25f;
    private static final float BASE_HEAD  = -0.15f;

    // SCALE = 1/16 (pixels to blocks)
    private static final float SCALE = 1.0f / 16.0f;

    private final Matrix4f scratch = new Matrix4f();

    public ZoloyModel() {
        // Head: 8x8x8, box from (-4,-8,-4) to (4,0,4)
        // ModelBox(u, v, w, h, d, ox, oy, oz) — ox,oy,oz in pixels (Y down)
        head = new ModelBox(0, 0, 8, 8, 8, -4, -8, -4);

        // Body: 8x12x4, box from (-4,0,-2) to (4,12,2)
        body = new ModelBox(16, 16, 8, 12, 4, -4, 0, -2);

        // Right arm: 4x12x4, box from (-2,-2,-2) to (2,10,2)
        rarm = new ModelBox(40, 16, 4, 12, 4, -2, -2, -2);

        // Left arm: 4x12x4, box from (-2,-2,-2) to (2,10,2)
        larm = new ModelBox(32, 48, 4, 12, 4, -2, -2, -2);

        // Right leg: 4x12x4, box from (-2,0,-2) to (2,12,2)
        rleg = new ModelBox(0, 16, 4, 12, 4, -2, 0, -2);

        // Left leg: 4x12x4, box from (-2,0,-2) to (2,12,2)
        lleg = new ModelBox(16, 48, 4, 12, 4, -2, 0, -2);

        // Cloak: 8x12x4, overlay expanded 0.5px, behind body
        cloak = new ModelBox(16, 28, 8, 12, 4, -4.5f, -0.5f, -2.5f, 0.5f);
    }

    private void renderPart(ModelBox part, float[] pivot, float rotX,
                           Matrix4f base, Matrix4f viewProj, Shader shader) {
        // Transform: translate to pivot, rotate, translate back
        scratch.identity();
        scratch.translate(pivot[0] * SCALE, pivot[1] * SCALE, pivot[2] * SCALE);
        scratch.rotateX(rotX);
        scratch.translate(-pivot[0] * SCALE, -pivot[1] * SCALE, -pivot[2] * SCALE);

        // mvp = viewProj * base * scratch
        Matrix4f mvp = viewProj.mul(base, new Matrix4f()).mul(scratch);
        shader.setUniformMat4("mvp", mvp);
        part.render();
    }

    /**
     * @param base entity matrix: translate(pos) * rotateY(yaw) * scale(0.8)
     * @param viewProj projection * view
     * @param shader active shader
     * @param limbSwing walk phase
     * @param limbSwingAmount 0..1
     * @param attackPhase 0..1
     * @param debugTpose if true, all rotX = 0
     */
    public void render(Matrix4f base, Matrix4f viewProj, Shader shader,
                       float limbSwing, float limbSwingAmount,
                       float attackPhase, boolean debugTpose) {

        float a = limbSwingAmount;

        // Vanilla formulas
        float rLegRot = (float) Math.cos(limbSwing * 0.6662f) * 1.4f * a;
        float lLegRot = (float) Math.cos(limbSwing * 0.6662f + Math.PI) * 1.4f * a;
        float rArmRot = (float) Math.cos(limbSwing * 0.6662f + Math.PI) * 1.0f * a;
        float lArmRot = (float) Math.cos(limbSwing * 0.6662f) * 1.0f * a;

        // Attack swing overrides right arm
        if (attackPhase > 0f) {
            float t = attackPhase;
            float arc = (float) Math.sin(t * Math.PI);
            rArmRot = -2.2f + 2.8f * arc;
        }

        if (debugTpose) {
            rLegRot = 0; lLegRot = 0; rArmRot = 0; lArmRot = 0;
        }

        // Render legs
        renderPart(rleg, PIVOT_RLEG, rLegRot, base, viewProj, shader);
        renderPart(lleg, PIVOT_LLEG, lLegRot, base, viewProj, shader);

        // Body with hunch
        renderPart(body, PIVOT_BODY, debugTpose ? 0 : BASE_BODY, base, viewProj, shader);

        // Arms with base posture
        renderPart(rarm, PIVOT_RARM, (debugTpose ? 0 : BASE_RARM) + rArmRot, base, viewProj, shader);
        renderPart(larm, PIVOT_LARM, (debugTpose ? 0 : BASE_LARM) + lArmRot, base, viewProj, shader);

        // Head
        renderPart(head, PIVOT_HEAD, debugTpose ? 0 : BASE_HEAD, base, viewProj, shader);

        // Cloak overlay (second pass, behind body)
        renderPart(cloak, PIVOT_CLOAK, debugTpose ? 0 : BASE_BODY * 0.5f, base, viewProj, shader);
    }

    public void cleanup() {
        head.cleanup();
        body.cleanup();
        rarm.cleanup();
        larm.cleanup();
        rleg.cleanup();
        lleg.cleanup();
        cloak.cleanup();
    }
}

