python -c "
import random
from PIL import Image

SIZE = 64
GRID = 16
SEED = 7

GRASS = [
    (47, 128, 36),
    (63, 156, 44),
    (80, 178, 52),
    (98, 198, 62),
    (116, 214, 74),
]
DIRT = [
    (77, 53, 38),
    (95, 67, 48),
    (113, 81, 58),
    (131, 95, 68),
]
STONE = [
    (110, 110, 110),
    (135, 135, 135),
    (160, 160, 160),
    (185, 185, 185),
]

S = SIZE // GRID

def fill(px, gx, gy, c):
    for y in range(gy * S, gy * S + S):
        for x in range(gx * S, gx * S + S):
            px[x, y] = c

def make_dirt(rng):
    img = Image.new('RGB', (SIZE, SIZE)); px = img.load()
    for gy in range(GRID):
        for gx in range(GRID):
            fill(px, gx, gy, rng.choice(DIRT))
    for _ in range(GRID * GRID // 40):
        gx, gy = rng.randrange(GRID), rng.randrange(GRID)
        c = rng.choice(STONE)
        fill(px, gx, gy, c)
        if rng.random() < 0.6:
            fill(px, (gx + 1) % GRID, gy, c)
        if rng.random() < 0.35:
            fill(px, gx, (gy + 1) % GRID, c)
    return img

def make_grass_top(rng):
    img = Image.new('RGB', (SIZE, SIZE)); px = img.load()
    for gy in range(GRID):
        for gx in range(GRID):
            fill(px, gx, gy, rng.choice(GRASS[1:]))
        if gy % 2 == 0:
            for gx in range(GRID):
                if rng.random() < 0.4:
                    fill(px, gx, gy, rng.choice(GRASS[:2]))
    return img

def make_grass_side(rng):
    img = make_dirt(rng); px = img.load()
    for gx in range(GRID):
        cap = 2 + rng.randrange(2)
        for gy in range(cap):
            fill(px, gx, gy, rng.choice(GRASS))
        if rng.random() < 0.5:
            for i in range(rng.randrange(2, 7)):
                gy = cap + i
                if gy >= GRID: break
                fill(px, gx, gy, rng.choice(GRASS[:3]))
                if rng.random() < 0.3:
                    fill(px, (gx + rng.choice((-1, 1))) % GRID, gy, GRASS[1])
    return img

rng = random.Random(SEED)
top, side, bottom = make_grass_top(rng), make_grass_side(rng), make_dirt(rng)

top.save('src/main/resources/textures/blocks/grass_top.png')
side.save('src/main/resources/textures/blocks/grass_side.png')
bottom.save('src/main/resources/textures/blocks/dirt.png')

atlas = Image.new('RGB', (SIZE * 3, SIZE))
for i, im in enumerate((top, side, bottom)):
    atlas.paste(im, (i * SIZE, 0))
atlas.save('atlas_strip.png')

print('Done: grass_top.png, grass_side.png, dirt.png, atlas_strip.png')
"

