python -c "
import random
from PIL import Image

SIZE = 64
GRID = 16
SEED = 21

BARK_LIGHT = [(238,236,224),(228,226,214),(218,216,204),(207,205,193)]
BARK_GRAY = [(168,166,156),(140,138,128),(110,108,100)]
BARK_DARK = [(52,50,46),(38,36,34),(70,68,62)]
WOOD_LIGHT = [(226,212,166),(216,202,156),(203,189,143)]
WOOD_DARK = [(178,162,118),(158,143,103)]
LEAF = [(52,92,34),(64,108,40),(78,126,48),(92,142,56),(108,160,66),(126,178,78)]
LEAF_HIGHLIGHT = (146,196,92)

S = SIZE // GRID

def fill(px, gx, gy, c):
    for y in range(gy*S, gy*S+S):
        for x in range(gx*S, gx*S+S):
            px[x,y] = c

def make_bark_side(rng):
    img = Image.new('RGB',(SIZE,SIZE)); px=img.load()
    for gy in range(GRID):
        for gx in range(GRID):
            c = rng.choice(BARK_LIGHT)
            if rng.random()<0.12: c=rng.choice(BARK_GRAY)
            fill(px,gx,gy,c)
    for _ in range(GRID//2+2):
        gx,gy=rng.randrange(GRID),rng.randrange(GRID)
        ln=rng.randrange(2,6)
        c=rng.choice(BARK_DARK)
        for i in range(ln): fill(px,(gx+i)%GRID,gy,c)
        if rng.random()<0.5: fill(px,(gx+ln)%GRID,gy,rng.choice(BARK_GRAY))
    for _ in range(GRID//2):
        gx,gy=rng.randrange(GRID),rng.randrange(GRID)
        fill(px,gx,gy,rng.choice(BARK_DARK))
        if rng.random()<0.4: fill(px,(gx+1)%GRID,(gy+1)%GRID,rng.choice(BARK_DARK))
    for _ in range(4):
        gx,gy=rng.randrange(GRID),rng.randrange(GRID)
        for i in range(rng.randrange(3,7)): fill(px,gx,(gy+i)%GRID,BARK_GRAY[0])
    return img

def make_log_top(rng):
    img = Image.new('RGB',(SIZE,SIZE)); px=img.load()
    half=GRID/2
    for gy in range(GRID):
        for gx in range(GRID):
            d=max(abs(gx-half+0.5),abs(gy-half+0.5))
            if d>=half-2:
                c=rng.choice(BARK_LIGHT)
                if rng.random()<0.3: c=rng.choice(BARK_DARK+BARK_GRAY)
            else:
                c=rng.choice(WOOD_DARK if int(d)%2 else WOOD_LIGHT)
            fill(px,gx,gy,c)
    return img

def make_leaves(rng):
    img = Image.new('RGBA',(SIZE,SIZE)); px=img.load()
    for gy in range(GRID):
        for gx in range(GRID):
            if rng.random()<0.08: fill(px,gx,gy,(0,0,0,0))
            else: fill(px,gx,gy,rng.choice(LEAF)+(255,))
    for _ in range(GRID):
        gx,gy=rng.randrange(GRID),rng.randrange(GRID)
        fill(px,gx,gy,LEAF_HIGHLIGHT+(255,))
        if rng.random()<0.5: fill(px,(gx+1)%GRID,gy,LEAF_HIGHLIGHT+(255,))
    for _ in range(GRID): fill(px,rng.randrange(GRID),rng.randrange(GRID),LEAF[0]+(255,))
    return img

rng=random.Random(SEED)
side=make_bark_side(rng); top=make_log_top(rng); leaves=make_leaves(rng)

side.save('src/main/resources/textures/blocks/birch_log_side.png')
top.save('src/main/resources/textures/blocks/birch_log_top.png')
leaves.save('src/main/resources/textures/blocks/birch_leaves.png')
print('Done: birch_log_side.png, birch_log_top.png, birch_leaves.png')
"

