/**
 * Generate water sources for oceans, rivers, and lakes.
 * Uses simple filling: water sources placed at sea level in low areas.
 */
private void generateWater(Chunk chunk, int originX, int originZ) {
    for (int x = 0; x < Chunk.SIZE; x++) {
        for (int z = 0; z < Chunk.SIZE; z++) {
            int wx = originX + x;
            int wz = originZ + z;
            int height = getHeight(wx, wz);

            // Ocean/beach: fill with water up to sea level
            if (height < SEA_LEVEL) {
                // Place water source at sea level
                chunk.setBlock(x, SEA_LEVEL, wz, BlockType.WATER.id);
                // Fill down to terrain
                for (int y = SEA_LEVEL - 1; y > height; y--) {
                    chunk.setBlock(x, y, wz, BlockType.WATER.id);
                }
            }

            // Rivers: carve and fill with water
            double r = riverNoise.fbm(wx, wz, 2, 0.00085, 0.5);
            if (Math.abs(r) < 0.035 && height >= SEA_LEVEL - 6 && height <= SEA_LEVEL + 10) {
                int waterLevel = Math.min(height, SEA_LEVEL - 1);
                chunk.setBlock(x, waterLevel, wz, BlockType.WATER.id);
            }

            // Lakes: depressions below sea level
            if (height >= SEA_LEVEL - 5 && height < SEA_LEVEL) {
                double lakeNoise = heightNoise.fbm(wx, wz, 2, 0.02, 0.5);
                if (lakeNoise < -0.25) {
                    // Fill depression with water
                    for (int y = SEA_LEVEL; y > height; y--) {
                        if (chunk.getBlock(x, y, wz) == BlockType.AIR.id) {
                            chunk.setBlock(x, y, wz, BlockType.WATER.id);
                        }
                    }
                }
            }
        }
    }
}

