    return AO_MIN + (1.0f - AO_MIN) * (level / 3.0f);
}

/** Quantize light to 8 levels for better greedy meshing. */
private static float quantizeLight(float light) {
    return Math.round(light * 8.0f) / 8.0f;
}

/** Quantize AO to 4 levels for better greedy meshing. */
private static float quantizeAO(float ao) {
    return Math.round(ao * 4.0f) / 4.0f;
}

