    if (w > 0.75 && t >= 0.4 && t <= 0.7 && h >= 0.3 && h <= 0.7) return MCBiome.LAVENDER_MEADOW;

    // Crystal peaks: low weirdness (valleys) + peaks slot
    if (w < 0.25 && pvLevel(pv).equals("peaks")) return MCBiome.CRYSTAL_PEAKS;

