package com.voxelgame.ui.screen;

import com.voxelgame.ui.FontRenderer;
import com.voxelgame.ui.GuiAssets;
import com.voxelgame.ui.UIRenderer;
import com.voxelgame.ui.widget.Button;

import java.util.ArrayList;
import java.util.List;
import java.util.Random;

import static com.voxelgame.core.Language.tr;

public class MainMenuScreen extends Screen {

    public interface Callbacks {
        void onSingleplayer();
        void onOptions();
        void onLanguage();
        void onQuit();
        String versionString();
    }

    private static final String TITLE = "VOXELCRAFT";

    private static final int BACKGROUND_TOP = 0xFF0A0A1A;
    private static final int BACKGROUND_BOTTOM = 0xFF1A0A2A;
    private static final int BUTTON_FILL = 0x33FFFFFF;
    private static final int BUTTON_HOVER = 0x6600FFFF;
    private static final int BUTTON_BORDER = 0xFF00FFFF;
    private static final int TEXT_PRIMARY = 0xFFFFFFFF;
    private static final int TEXT_SECONDARY = 0xFF8888AA;
    private static final int GLOW_COLOR = 0xFF00FFFF;

    private final Callbacks callbacks;
    private double time = 0;

    private final List<Particle> particles = new ArrayList<>();
    private final Random rnd = new Random(42);

    private float[] buttonAnimProgress;
    private static final float ANIM_DURATION = 0.8f;
    private static final float ANIM_STAGGER = 0.12f;

    private static class Particle {
        float x, y;
        float vx, vy;
        float size;
        int color;
        float alpha;

        Particle(float x, float y, float vx, float vy, float size, int color, float alpha) {
            this.x = x;
            this.y = y;
            this.vx = vx;
            this.vy = vy;
            this.size = size;
            this.color = color;
            this.alpha = alpha;
        }
    }

    public MainMenuScreen(Callbacks callbacks) {
        this.callbacks = callbacks;
    }

    @Override
    public boolean rendersWorld() {
        return false;
    }

    @Override
    public boolean usesPanorama() {
        return false;
    }

    @Override
    public boolean closableWithEscape() {
        return false;
    }

    @Override
    protected void layout() {
        int bw = 200;
        int bh = 28;
        int spacing = 34;

        int cx = (width - bw) / 2;
        int startY = height / 2 + 10;

        widgets.clear();

        Button sp = add(new Button(cx, startY, bw, bh, tr("menu.singleplayer"),
                b -> callbacks.onSingleplayer()));
        sp.animDelay = 0;

        Button opts = add(new Button(cx, startY + spacing, bw, bh, tr("menu.options"),
                b -> callbacks.onOptions()));
        opts.animDelay = ANIM_STAGGER;

        Button quit = add(new Button(cx, startY + spacing * 2, bw, bh, tr("menu.quit"),
                b -> callbacks.onQuit()));
        quit.animDelay = ANIM_STAGGER * 2;

        Button lang = add(new Button(width - 34, height - 26, 20, 20, "\uD83C\uDF10",
                b -> callbacks.onLanguage()));
        lang.animDelay = ANIM_STAGGER * 3;

        buttonAnimProgress = new float[widgets.size()];
        for (int i = 0; i < buttonAnimProgress.length; i++) {
            buttonAnimProgress[i] = 0;
        }

        initParticles();
    }

    private void initParticles() {
        particles.clear();
        int count = 60;
        for (int i = 0; i < count; i++) {
            float x = rnd.nextFloat() * width;
            float y = rnd.nextFloat() * height;
            float vx = (rnd.nextFloat() - 0.5f) * 6;
            float vy = (rnd.nextFloat() - 0.5f) * 4 - 1;
            float size = 1 + rnd.nextFloat() * 2;
            int color = rnd.nextFloat() > 0.7f ? GLOW_COLOR : 0xFF4466AA;
            float alpha = 0.2f + rnd.nextFloat() * 0.5f;
            particles.add(new Particle(x, y, vx, vy, size, color, alpha));
        }
    }

    @Override
    public void update(double deltaTime) {
        time += deltaTime;

        for (int i = 0; i < buttonAnimProgress.length && i < widgets.size(); i++) {
            if (widgets.get(i) instanceof Button btn) {
                float target = 1.0f;
                float delay = btn.animDelay;
                float t = (float) (time * 2.5 - delay);
                float progress = Math.max(0, Math.min(1, t / ANIM_DURATION));
                buttonAnimProgress[i] = easeOutCubic(progress);
            }
        }

        for (Particle p : particles) {
            p.x += p.vx * (float) deltaTime * 20;
            p.y += p.vy * (float) deltaTime * 20;

            if (p.x < -10) p.x = width + 10;
            if (p.x > width + 10) p.x = -10;
            if (p.y < -10) p.y = height + 10;
            if (p.y > height + 10) p.y = -10;
        }
    }

    private float easeOutCubic(float t) {
        return 1.0f - (float) Math.pow(1.0f - t, 3);
    }

    @Override
    protected void renderBackground(UIRenderer ui, FontRenderer font, GuiAssets tex) {
        ui.fillGradientV(0, 0, width, height, BACKGROUND_TOP, BACKGROUND_BOTTOM);

        for (Particle p : particles) {
            int color = ((int) (p.alpha * 255) << 24) | (p.color & 0xFFFFFF);
            ui.drawParticle(p.x, p.y, p.size, color);
        }
    }

    @Override
    protected void renderForeground(UIRenderer ui, FontRenderer font, GuiAssets tex,
                                    float mx, float my) {
        drawNeonLogo(ui, font);

        for (int i = 0; i < widgets.size(); i++) {
            Widget w = widgets.get(i);
            if (buttonAnimProgress[i] > 0 && buttonAnimProgress[i] <= 1) {
                float offset = (1 - buttonAnimProgress[i]) * 30;
                float scale = 0.95f + buttonAnimProgress[i] * 0.05f;
                int alpha = (int) (buttonAnimProgress[i] * 255) << 24;

                w.y = (int) (w.baseY + offset);
                w.alpha = alpha;
            }
            w.updateHover(mx, my);
            w.render(ui, font, tex, mx, my);
        }

        font.drawWithShadow(ui, callbacks.versionString(),
                4, height - FontRenderer.GLYPH_H - 4, TEXT_SECONDARY);
    }

    private void drawNeonLogo(UIRenderer ui, FontRenderer font) {
        float glowPulse = 0.6f + 0.4f * (float) Math.sin(time * 2.0);
        int glowAlpha = (int) (glowPulse * 80);

        int scale = 3;
        int textW = font.scaledWidth(TITLE, scale);
        float x = (width - textW) / 2.0f;
        float y = Math.max(20, height / 2.0f - 90);

        for (int i = 4; i > 0; i--) {
            int glowColor = ((glowAlpha / i) << 24) | (GLOW_COLOR & 0xFFFFFF);
            font.drawScaled(ui, TITLE, x - i, y - i, scale, glowColor);
            font.drawScaled(ui, TITLE, x + i, y - i, scale, glowColor);
            font.drawScaled(ui, TITLE, x - i, y + i, scale, glowColor);
            font.drawScaled(ui, TITLE, x + i, y + i, scale, glowColor);
        }

        font.drawScaledWithShadow(ui, TITLE, x, y, scale, TEXT_PRIMARY);

        int subScale = 1;
        int subW = font.scaledWidth("voxel engine", subScale);
        float sx = (width - subW) / 2.0f;
        float sy = y + scale * FontRenderer.GLYPH_H + 8;
        font.drawScaledWithShadow(ui, "voxel engine", sx, sy, subScale, TEXT_SECONDARY);

        float lineY = sy + FontRenderer.GLYPH_H + 10;
        float lineW = 80;
        float lineX = (width - lineW) / 2;
        int lineAlpha = (int) (glowPulse * 120) << 24;
        ui.fillRect(lineX, lineY, lineW, 1, lineAlpha | (GLOW_COLOR & 0xFFFFFF));
    }
}

package com.voxelgame.ui.widget;

import com.voxelgame.ui.FontRenderer;
import com.voxelgame.ui.UIRenderer;
import com.voxelgame.ui.GuiAssets;

public abstract class Widget {
    public int x, y, width, height;
    public boolean visible = true;
    public boolean enabled = true;

    public int baseY;
    public int alpha = 255;
    public float animDelay = 0;

    protected boolean hovered = false;

    protected Widget(int x, int y, int width, int height) {
        this.x = x;
        this.y = y;
        this.baseY = y;
        this.width = width;
        this.height = height;
    }

    public boolean contains(float mx, float my) {
        return mx >= x && mx < x + width && my >= y && my < y + height;
    }

    public void updateHover(float mx, float my) {
        hovered = visible && enabled && contains(mx, my);
    }

    public boolean isHovered() { return hovered; }

    public void update(double deltaTime) {}

    public abstract void render(UIRenderer ui, FontRenderer font, GuiAssets tex, float mx, float my);

    public boolean mouseClicked(float mx, float my, int button) {
        return false;
    }

    public void mouseReleased(float mx, float my, int button) {}

    public boolean mouseDragged(float mx, float my, int button) {
        return false;
    }

    public boolean mouseScrolled(float mx, float my, double delta) {
        return false;
    }

    public boolean keyPressed(int key, int mods) {
        return false;
    }
}

package com.voxelgame.ui.widget;

import com.voxelgame.ui.FontRenderer;
import com.voxelgame.ui.UIRenderer;
import com.voxelgame.ui.GuiAssets;

public class Button extends Widget {

    public interface Action {
        void onPress(Button source);
    }

    private String label;
    private final Action action;

    private static final int TEXT_NORMAL = 0xFFE0E0E0;
    private static final int TEXT_HOVER = 0xFFFFFFFF;
    private static final int TEXT_DISABLED = 0xFF666666;

    private static final int BUTTON_FILL_NORMAL = 0x22FFFFFF;
    private static final int BUTTON_FILL_HOVER = 0x4400FFFF;
    private static final int BUTTON_BORDER_NORMAL = 0x66FFFFFF;
    private static final int BUTTON_BORDER_HOVER = 0xFF00FFFF;
    private static final int GLOW_COLOR = 0xFF00FFFF;

    public Button(int x, int y, int width, int height, String label, Action action) {
        super(x, y, width, height);
        this.label = label;
        this.action = action;
    }

    public void setLabel(String label) { this.label = label; }
    public String getLabel() { return label; }

    private float hoverProgress = 0;
    private float scaleProgress = 1.0f;

    @Override
    public void update(double deltaTime) {
        float target = hovered ? 1.0f : 0.0f;
        hoverProgress += (target - hoverProgress) * (float) Math.min(1.0, deltaTime * 12);
        scaleProgress += ((1.0f + hoverProgress * 0.03f) - scaleProgress) * (float) Math.min(1.0, deltaTime * 10);
    }

    @Override
    public void render(UIRenderer ui, FontRenderer font, GuiAssets tex, float mx, float my) {
        if (!visible) return;

        if (!enabled) {
            ui.fillRoundedRect(x, y, width, height, 5, 0x11FFFFFF);
            ui.drawNeonBorder(x, y, width, height, 0xFF333333);
            font.drawCenteredWithShadow(ui, label,
                    x + width / 2.0f, y + (height - FontRenderer.GLYPH_H) / 2.0f,
                    TEXT_DISABLED);
            return;
        }

        float centerX = x + width / 2.0f;
        float centerY = y + height / 2.0f;
        float scaledW = width * scaleProgress;
        float scaledH = height * scaleProgress;
        float drawX = centerX - scaledW / 2;
        float drawY = centerY - scaledH / 2;

        if (hoverProgress > 0.01f) {
            float glowIntensity = hoverProgress * (0.7f + 0.3f * (float) Math.sin(System.currentTimeMillis() * 0.003));
            ui.drawGlow(drawX, drawY, scaledW, scaledH, GLOW_COLOR, glowIntensity);
        }

        int bgFill = lerpColor(BUTTON_FILL_NORMAL, BUTTON_FILL_HOVER, hoverProgress);
        int borderCol = lerpColor(BUTTON_BORDER_NORMAL, BUTTON_BORDER_HOVER, hoverProgress);

        int finalAlpha = (alpha << 24) >>> 24;
        bgFill = ((int) ((bgFill >>> 24) / 255.0f * finalAlpha) << 24) | (bgFill & 0xFFFFFF);
        borderCol = ((int) ((borderCol >>> 24) / 255.0f * finalAlpha) << 24) | (borderCol & 0xFFFFFF);

        ui.fillRoundedRect(drawX, drawY, scaledW, scaledH, 5, bgFill);
        ui.drawNeonBorder(drawX, drawY, scaledW, scaledH, borderCol);

        int textColor = lerpColor(TEXT_NORMAL, TEXT_HOVER, hoverProgress);
        textColor = ((int) ((textColor >>> 24) / 255.0f * finalAlpha) << 24) | (textColor & 0xFFFFFF);

        float textY = drawY + (scaledH - FontRenderer.GLYPH_H) / 2.0f;
        font.drawCenteredWithShadow(ui, label, drawX + scaledW / 2.0f, textY, textColor);
    }

    private int lerpColor(int c1, int c2, float t) {
        int a1 = (c1 >>> 24) & 0xFF;
        int r1 = (c1 >> 16) & 0xFF;
        int g1 = (c1 >> 8) & 0xFF;
        int b1 = c1 & 0xFF;

        int a2 = (c2 >>> 24) & 0xFF;
        int r2 = (c2 >> 16) & 0xFF;
        int g2 = (c2 >> 8) & 0xFF;
        int b2 = c2 & 0xFF;

        int a = (int) (a1 + (a2 - a1) * t);
        int r = (int) (r1 + (r2 - r1) * t);
        int g = (int) (g1 + (g2 - g1) * t);
        int b = (int) (b1 + (b2 - b1) * t);

        return (a << 24) | (r << 16) | (g << 8) | b;
    }

    @Override
    public boolean mouseClicked(float mx, float my, int button) {
        if (!visible || !enabled || button != 0 || !contains(mx, my)) return false;
        if (action != null) action.onPress(this);
        return true;
    }
}

