/**
     * Face visibility with cross-chunk seam awareness.
     * When the neighbour chunk is loaded, checks if the neighbour's terrain
     * column actually reaches up to or above this face position — if so,
     * the neighbour is taller here and this face must be rendered from THIS
     * side (hidden from the neighbour's shorter column).
     *
     * @param wx world x of the face position
     * @param wy world y of the face position
     * @param wz world z of the face position
     * @param face 0..5 per FACE_OFFSETS
     * @param blockId this block's ID
     * @param neighborId neighbour's block ID (may be 0 if not loaded)
     */
    public static boolean facePassesCrossChunk(World world, int wx, int wy, int wz,
                                                int face, byte blockId, byte neighborId) {
        if (neighborId == 0) {
            // Neighbor not loaded: use heightmap to detect if the neighbour
            // column is taller than this face — if so, skip (neighbour's
            // taller face covers ours). -1 = unknown height = render conservatively
            int cx = wx >> 4;
            int cz = wz >> 4;
            int nx = wx + FACE_OFFSETS[face][0];
            int nz = wz + FACE_OFFSETS[face][2];
            int ncx = nx >> 4;
            int ncz = nz >> 4;

            if (ncx != cx || ncz != cz) {
                Chunk nc = world.getChunk(ncx, ncz);
                if (nc != null) {
                    int h = nc.getHighestBlock(nx & (Chunk.SIZE - 1), nz & (Chunk.SIZE - 1));
                    // If neighbour's column is taller than our face y, our face
                    // is "inside" neighbour's terrain and should NOT be rendered.
                    // Only skip if wy < h (our face is below neighbour's top)
                    if (wy < h) return false;
                }
            }
            return true; // unloaded or our face is above neighbour's top
        }

