import com.voxelgame.world.biome.*;
import java.util.*;

public class BiomeProbe {
    public static void main(String[] args) {
        long[] seeds = {12345, 67890, 11111};
        for (long seed : seeds) {
            BiomeNoise noise = new BiomeNoise(seed);
            BiomeSelector selector = new BiomeSelector();
            Map<BiomeSelector.MCBiome, Integer> counts = new HashMap<>();
            int sampleArea = 2048;
            int step = Math.max(1, sampleArea / 64);
            int total = 0;
            for (int x = -sampleArea/2; x < sampleArea/2; x += step) {
                for (int z = -sampleArea/2; z < sampleArea/2; z += step) {
                    BiomeSelector.MCBiome biome = selector.select(
                        noise.T(x, z), noise.H(x, z), noise.C(x, z),
                        noise.E(x, z), noise.W(x, z), noise.PV(x, z));
                    counts.merge(biome, 1, Integer::sum);
                    total++;
                }
            }
            System.out.println("Seed " + seed + " (" + counts.size() + " biomes, total " + total + "):");
            counts.entrySet().stream()
                .sorted((a, b) -> b.getValue() - a.getValue())
                .forEach(e -> {
                    double pct = e.getValue() * 100.0 / total;
                    System.out.printf("    %-28s %6.1f%% %s%n", e.getKey(), pct,
                        (pct < 0.5 || pct > 35) ? "  <-- OUT OF RANGE" : "");
                });
        }
    }
}

