package com.voxelgame.world.plank;

import com.voxelgame.world.BlockType;

/**
 * Wood species available for the improved plank system.
 *
 * Hardness/resistance are in the engine's block scale (oak planks = 2.0).
 * Flammability is the block-burn chance from {@link BlockType#flammability}.
 * Water resistance is metadata only: the engine has no rot/water damage.
 */
public enum WoodSpecies {

    OAK("oak", 2.0f, 2.0f, 0.15f, 0, BlockType.OAK_LOG, 0xB8905A),
    SPRUCE("spruce", 2.0f, 2.0f, 0.15f, 0, BlockType.SPRUCE_LOG, 0x7A5A3A),
    BIRCH("birch", 2.0f, 2.0f, 0.15f, 0, BlockType.BIRCH_LOG, 0xD8C898),
    JUNGLE("jungle", 2.0f, 2.0f, 0.15f, 0, BlockType.JUNGLE_LOG, 0xB08050);

    public final String id;
    public final String langKey;
    public final float hardness;
    public final float resistance;
    public final float flammability;
    public final int waterResistance;
    public final BlockType logBlock;
    public final int baseColor;

    WoodSpecies(String id, float hardness, float resistance, float flammability,
                int waterResistance, BlockType logBlock, int baseColor) {
        this.id = id;
        this.langKey = "wood." + id;
        this.hardness = hardness;
        this.resistance = resistance;
        this.flammability = flammability;
        this.waterResistance = waterResistance;
        this.logBlock = logBlock;
        this.baseColor = baseColor;
    }

    /** Look up by registry id ("oak"), or null. */
    public static WoodSpecies fromId(String id) {
        for (WoodSpecies s : values()) {
            if (s.id.equals(id)) return s;
        }
        return null;
    }
}

package com.voxelgame.world.plank;

/**
 * A treatment applied to a wood species: drying, sealing, charring, ...
 *
 * The multipliers feed the Part-6 property formulas:
 *   hardness      = species.hardness      * hardnessMultiplier
 *   resistance    = species.resistance    * resistanceMultiplier
 *   flammability  = species.flammability  * flammabilityMultiplier
 *   waterResist   = species.waterResistance + waterResistanceBonus
 *
 * {@code fireProof} treatments never catch fire at all.
 */
public enum PlankTreatment {

    RAW("raw", 0.9f, 0.8f, 1.6f, -2, false),
    DRIED("dried", 1.0f, 1.0f, 1.0f, 0, false),
    SEALED("sealed", 1.05f, 1.1f, 0.9f, 4, false),
    CHARRED("charred", 0.85f, 0.9f, 0.0f, 3, true),
    REINFORCED("reinforced", 1.4f, 1.8f, 0.3f, 2, false),
    COMPOSITE("composite", 1.2f, 1.3f, 0.5f, 3, false),
    WAXED("waxed", 1.0f, 1.0f, 1.0f, 5, false),
    LACQUERED("lacquered", 1.0f, 1.1f, 1.3f, 4, false);

    public final String id;
    public final String langKey;
    public final float hardnessMultiplier;
    public final float resistanceMultiplier;
    public final float flammabilityMultiplier;
    public final int waterResistanceBonus;
    public final boolean fireProof;

    PlankTreatment(String id, float hardnessMultiplier, float resistanceMultiplier,
                   float flammabilityMultiplier, int waterResistanceBonus, boolean fireProof) {
        this.id = id;
        this.langKey = "plankTreatment." + id;
        this.hardnessMultiplier = hardnessMultiplier;
        this.resistanceMultiplier = resistanceMultiplier;
        this.flammabilityMultiplier = flammabilityMultiplier;
        this.waterResistanceBonus = waterResistanceBonus;
        this.fireProof = fireProof;
    }

    /** Look up by registry id ("dried"), or null. */
    public static PlankTreatment fromId(String id) {
        for (PlankTreatment t : values()) {
            if (t.id.equals(id)) return t;
        }
        return null;
    }
}

package com.voxelgame.world.plank;

/**
 * The shape a plank material takes.
 *
 * PLANKS and SLAB are fully implemented by the engine (full cubes and
 * half-height slabs). The rest are recognised forms the engine does not
 * mesh/collide yet: they stay registered as data with {@code isComplex}
 * true and are skipped by the block registry (see the report in
 * {@link PlankResourceGenerator}).
 */
public enum PlankForm {

    PLANKS("planks", "full", false),
    SLAB("slab", "slab", false),

    // --- Engine does not support these shapes yet: data only ---
    STAIRS("stairs", "stairs", true),
    FENCE("fence", "fence", true),
    FENCE_GATE("fence_gate", "fence_gate", true),
    DOOR("door", "door", true),
    TRAPDOOR("trapdoor", "trapdoor", true),
