package com.voxelgame.world.plank;

/**
 * One concrete block: a wood species + treatment + form combination.
 *
 * Registry ids follow the {wood}_{treatment}_{form} convention:
 *   oak_dried_planks, spruce_charred_slab, ...
 * Slabs and planks share the {wood}_{treatment}_planks texture.
 */
public final class PlankVariant {

    public final WoodSpecies species;
    public final PlankTreatment treatment;
    public final PlankForm form;

    public PlankVariant(WoodSpecies species, PlankTreatment treatment, PlankForm form) {
        this.species = species;
        this.treatment = treatment;
        this.form = form;
    }

    public String getId() {
        return species.id + "_" + treatment.id + "_" + form.id;
    }

    public String getLangKey() {
        return "block." + getId();
    }

    /** The block's registry name, e.g. "oak_dried_planks". */
    public String getBlockRegistryName() {
        return getId();
    }

    /** Items for blocks are implicit in this engine (ItemStack(BlockType)). */
    public String getItemRegistryName() {
        return getId();
    }

    /** Base texture name shared by the form's block, e.g. "oak_dried_planks". */
    public String getTextureBaseName() {
        return species.id + "_" + treatment.id + "_planks";
    }

    // --- Part-6 property formulas ---

    public float getHardness() {
        return species.hardness * treatment.hardnessMultiplier;
    }

    public float getResistance() {
        return species.resistance * treatment.resistanceMultiplier;
    }

    public float getFlammability() {
        return species.flammability * treatment.flammabilityMultiplier;
    }

    public int getWaterResistance() {
        return species.waterResistance + treatment.waterResistanceBonus;
    }

    public boolean isFireProof() {
        return treatment.fireProof;
    }
}

package com.voxelgame.world.plank;

import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

/**
 * Registry of every improved-plank block: 4 species x 8 treatments x the
 * engine-supported forms. Complex forms (stairs, fences, doors, ...) stay
 * in the list for reporting but are never turned into blocks.
 */
public final class PlankBlockRegistry {

    /** Every species x treatment x form combination, in registration order. */
    public static final List<PlankVariant> ALL = new ArrayList<>();

    /** Only the engine-supported, registrable variants (planks + slabs). */
    public static final List<PlankVariant> REGISTERED = new ArrayList<>();

    static {
        for (WoodSpecies species : WoodSpecies.values()) {
            for (PlankTreatment treatment : PlankTreatment.values()) {
                for (PlankForm form : PlankForm.values()) {
                    PlankVariant v = new PlankVariant(species, treatment, form);
                    ALL.add(v);
                    if (!form.isComplex) {
                        REGISTERED.add(v);
                    }
                }
            }
        }
    }

    private static final Map<String, PlankVariant> BY_ID = new LinkedHashMap<>();
    static {
        for (PlankVariant v : ALL) {
            BY_ID.put(v.getId(), v);
        }
    }

    /** Look up a variant by registry id ("oak_dried_planks"), or null. */
    public static PlankVariant fromId(String id) {
        return BY_ID.get(id);
    }

    private PlankBlockRegistry() {}
}

