    public static float flammability(byte blockId) {
        BlockType t = fromId(blockId);
        if (t == TNT) return 1.0f;
        if (t == FIRE) return 0.0f;
        if (t == WHITE_WOOL) return 0.9f;
        if (t == DEAD_BUSH || t == GRASS_PLANT || t == WHEAT || t == CARROT
