            case "screenshot" -> takeScreenshot(t.length > 1 ? t[1] : "debug_shot.png");

            case "tp" -> {
                requirePlayer(out);
                float x = num(t, 1), y = num(t, 2), z = num(t, 3);
                player.getPosition().set(x, y, z);
                camera.setPosition(new Vector3f(x, y + eyeHeight, z));
                player.setVerticalVelocity(0);
