import math, numpy as np

# JOML-style right-handed rotations: rotateX(theta): +Y -> +Z
def rx(t):
    c, s = math.cos(t), math.sin(t)
    return np.array([[1,0,0],[0,c,-s],[0,s,c]])

def ry(t):
    c, s = math.cos(t), math.sin(t)
    return np.array([[c,0,s],[0,1,0],[-s,0,c]])

def T(v):
    m = np.eye(4); m[:3,3] = v; return m

# ModelBox boxes: (u,v,w,h,d, ox,oy,oz) with Y-up, 1px = 1/16
BOXES = {
 'head': (0,0,8,8,8, -4,0,-4),
 'body': (16,16,8,12,4, -4,0,-2),
 'rarm': (40,16,4,12,4, -7,0,-2),
 'larm': (32,48,4,12,4, 3,0,-2),
 'rleg': (0,16,4,12,4, -5.9,12,-2),
 'lleg': (16,48,4,12,4, 1.9,12,-2),
 'nose': (24,0,2,4,2, -1,2,-6),
}
PIV = {
 'head': (0,0,0), 'body': (0,0,0), 'rarm': (-5,2,0), 'larm': (5,2,0),
 'rleg': (-1.9,12,0), 'lleg': (1.9,12,0), 'nose': (0,0,0),
}
P = 1/16.0

def corners(box):
    u,v,w,h,d,ox,oy,oz = box
    pts = []
    for dx in (0,w):
        for dy in (0,h):
            for dz in (0,d):
                pts.append([(ox+dx)*P,(oy+dy)*P,(oz+dz)*P,1])
    return np.array(pts).T

def scratch(rot_x, pivot):
    px,py,pz = pivot
    return T([px,-py,pz]) @ rx(rot_x) @ T([-px,py,-pz])

def render(pose, grid, char):
    # base = Y-flip * scale 0.8 (no translate/rotateY for local view)
    base = np.diag([0.8,-0.8,0.8,1.0])
    for name, rot in pose.items():
        s = scratch(-rot, PIV[name])  # matches renderPart: rotateX(-rotX)
        m = base @ s
        for v in corners(BOXES[name]).T:
            w = (m @ v)
            if w[3] != 0: w = w/w[3]
            gx = round(w[0]/0.05)+20
            gy = round(w[1]/0.05)+20
            if 0 <= gx < 40 and 0 <= gy < 40:
                grid[gy][gx] = char
    # mark front (-Z) and back (+Z) regions for side view
    return grid

