import math, numpy as np

def rx(t):
    c, s = math.cos(t), math.sin(t)
    return np.array([[1,0,0,0],[0,c,-s,0],[0,s,c,0],[0,0,0,1]])

def T(v):
    m = np.eye(4); m[:3,3] = v; return m

BOXES = {
 'head': (0,0,8,8,8, -4,0,-4), 'body': (16,16,8,12,4, -4,0,-2),
 'rarm': (40,16,4,12,4, -7,0,-2), 'larm': (32,48,4,12,4, 3,0,-2),
 'rleg': (0,16,4,12,4, -5.9,12,-2), 'lleg': (16,48,4,12,4, 1.9,12,-2),
 'nose': (24,0,2,4,2, -1,2,-6),
}
PIV = {'head': (0,0,0), 'body': (0,0,0), 'rarm': (-5,2,0), 'larm': (5,2,0),
       'rleg': (-1.9,12,0), 'lleg': (1.9,12,0), 'nose': (0,0,0)}
CH = {'head':'H','body':'B','rarm':'R','larm':'L','rleg':'l','lleg':'l','nose':'N'}
P = 1/16.0

def box_verts(box):
    u,v,w,h,d,ox,oy,oz = box
    pts = []
    for dx in (0,w):
        for dy in (0,h):
            for dz in (0,d):
                pts.append([(ox+dx)*P,(oy+dy)*P,(oz+dz)*P,1])
    return np.array(pts).T

FACES = [(0,1,3,2),(4,5,7,6),(0,1,5,4),(2,3,7,6),(0,2,6,4),(1,3,7,5)]  # 6 faces as corner idx quads

def scratch(rot_x, pivot):
    px,py,pz = pivot
    return T([px,-py,pz]) @ rx(rot_x) @ T([-px,py,-pz])

def project(m, v):
    w = m @ v
    if abs(w[3]) < 1e-9: return None
    return w[:3]/w[3]

def fill(grid, poly, ch):
    xs = [round(p[0]) for p in poly]; ys = [round(p[1]) for p in poly]
    for y in range(min(ys), max(ys)+1):
        hits = []
        for i in range(len(poly)):
            x1,y1 = poly[i]; x2,y2 = poly[(i+1)%len(poly)]
            if y1 == y2: continue
            if (y1 <= y < y2) or (y2 <= y < y1):
                t = (y - y1)/(y2 - y1)
                hits.append(x1 + t*(x2 - x1))
        if hits:
