        larm  = new ModelBox(32, 48, 4, 12, 4, 3, 0, -2, 0, true);
        rleg  = new ModelBox(0, 16, 4, 12, 4, -5.9f, 12, -2, 0, true);
        lleg  = new ModelBox(16, 48, 4, 12, 4, 1.9f, 12, -2, 0, true);
        cloak = new ModelBox(16, 28, 8, 12, 4, -4.5f, -0.5f, -2.5f, 0.5f, true);
