    /**
     * Искать ближайшую деревню к точке (px, pz). Использует ту же
     * детерминированную сетку, что и генератор деревень, поэтому деревня
     * будет сгенерирована при загрузке этих чанков.
     *
     * @return {x, y, z} точки телепортации (центр деревни, чуть над землёй)
     *         или null, если поблизости деревень нет
     */
    public float[] findNearestVillage(float px, float pz) {
        int pcx = (int) Math.floor(px / Chunk.SIZE);
        int pcz = (int) Math.floor(pz / Chunk.SIZE);

        int[] vc = villageGenerator.nearestVillageChunk(pcx, pcz, 4);
        if (vc == null) return null;

        int cx = vc[0] * Chunk.SIZE + 8;
        int cz = vc[1] * Chunk.SIZE + 8;
        int cy = generator.getHeight(cx, cz);
        if (cy < TerrainGenerator.SEA_LEVEL + 2) return null; // под водой — деревни нет

        return new float[]{cx + 0.5f, cy + 3.0f, cz + 0.5f};
    }

