#!/usr/bin/env python3
"""Проверка HD-текстур жителей: регионы заполнены, цвета в норме."""
import os, sys
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from PIL import Image

TILE = 1024
OUT = os.path.join(os.path.dirname(os.path.dirname(os.path.abspath(__file__))),
                   "src", "main", "resources", "textures", "entities")

UV = {
    "head_top": (8,0,8,8), "head_bot": (16,0,8,8), "head_right": (0,8,8,8),
    "head_front": (8,8,8,8), "head_left": (16,8,8,8), "head_back": (24,8,8,8),
    "body_top": (20,16,8,4), "body_bot": (28,16,8,4), "body_right": (16,20,4,12),
    "body_front": (20,20,8,12), "body_left": (28,20,4,12), "body_back": (32,20,8,12),
    "rarm_front": (44,20,4,12), "rarm_bot": (48,16,4,4),
    "rleg_front": (4,20,4,12), "lleg_front": (20,52,4,12),
    "nose_front": (26,2,2,4), "nose_top": (26,0,2,2), "nose_bot": (28,0,2,2),
    "nose_right": (24,2,2,4), "nose_left": (28,2,2,4), "nose_back": (30,2,2,4),
}

PROFS = ["farmer","librarian","blacksmith","butcher","priest","fisherman",
         "fletcher","leatherworker","shepherd","toolsmith","armorer",
         "weaponsmith","cartographer","cleric","mason","nitwit"]

def stats(img, key):
    x, y, w, h = (v * 16 for v in UV[key])
    xs, ys, xe, ye = x, y, x+w, y+h
    px = img.load()
    n = opaque = 0
    rsum = gsum = bsum = 0.0
    for yy in range(ys, ye):
        for xx in range(xs, xe):
            r, g, b, a = px[xx, yy]
            n += 1
            if a > 200:
                opaque += 1
                rsum += r; gsum += g; bsum += b
    if opaque == 0:
        return None
    return (opaque / n, rsum/opaque, gsum/opaque, bsum/opaque)

def check_face(img):
    """Глаза: белые склера в ожидаемых местах."""
    x, y = 8*16, 8*16
    px = img.load()
    found = 0
    for ex in (1, 5):
        for yy in range(y+2*16+10, y+3*16+22):
            for xx in range(x+ex*16+10, x+(ex+2)*16-10):
                r, g, b, a = px[xx, yy]
                if a > 200 and r > 225 and g > 225 and b > 220:
                    found += 1
                    break
            if found:
                break
    return found >= 2

fails = []
for prof in PROFS:
    img = Image.open(os.path.join(OUT, f"villager_{prof}.png"))
    assert img.size == (TILE, TILE), f"{prof}: size {img.size}"
    res = {k: stats(img, k) for k in UV}
    empty = [k for k, v in res.items() if v is None]
    if empty:
        fails.append(f"{prof}: пустые регионы {empty}")
    # лицо должно иметь белки глаз
    if not check_face(img):
        fails.append(f"{prof}: не найдены белки глаз")
    # тело не должно быть пустым
    if res["body_front"] is None or res["head_front"] is None:
        fails.append(f"{prof}: нет лица/тела")
    print(f"{prof:15s} лицо={res['head_front'][0]:.0%} тело={res['body_front'][0]:.0%} "
          f"нос={res['nose_front'][0]:.0%} руки={res['rarm_front'][0]:.0%} "
          f"ноги={res['rleg_front'][0]:.0%}")

# атлас
atlas = Image.open(os.path.join(OUT, "villager_atlas.png"))
print(f"\natlas: {atlas.size[0]}x{atlas.size[1]} (ожидается 16384x1024)")
if atlas.size != (16384, 1024):
    fails.append(f"атлас {atlas.size}")
for i, prof in enumerate(PROFS):
    tile = atlas.crop((i*TILE, 0, (i+1)*TILE, TILE))
    if tile.getbbox() is None:
        fails.append(f"атлас: тайл {prof} пуст")

for name in ("villager_baby.png", "villager_zombie.png"):
    img = Image.open(os.path.join(OUT, name))
    if img.size != (TILE, TILE):
        fails.append(f"{name}: размер {img.size}")
    print(f"{name}: {img.size}, непрозрачность {img.getbbox()}")

print()
if fails:
    print("ОШИБКИ:")
    for f in fails:
        print(" -", f)
    sys.exit(1)
print("OK: все проверки пройдены")

