private void updateWork(float dt) {
    if (!hasWork) {
        updateWander(dt);
        return;
    }

    // Сначала нашли цель, потом "работаем" над ней workTimer секунд
    if (!hasWorkTarget) {
        findWorkTarget();
        workTimer = 6.0f + (float) Math.random() * 8.0f;
    }

    float tx = workTarget.x - position.x;
    float tz = workTarget.z - position.z;
    float dist = (float) Math.sqrt(tx * tx + tz * tz);

    if (dist > 1.2f) {
        // Идут к цели (рабочее место, грядка или берег)
        desiredYaw = (float) Math.atan2(-tx, -tz);
        moveToward(workTarget, getWalkSpeed() * 0.85f, dt);
        stuckTimer += dt;
        if (stuckTimer > 3.5f) {
            // Не дошли — сменим цель (или просто бродят)
            hasWorkTarget = false;
            stuckTimer = 0;
        }
    } else {
        // На месте — "работают": руки в деле, изредка короткая речь
        velocity.x *= 0.85f;
        velocity.z *= 0.85f;
        desiredYaw = (float) Math.atan2(-tx, -tz);
        workTimer -= dt;
        limbSwingAmount = 0.30f; // анимация работы руками
        if (Math.random() < 0.012f) {
            isTalking = true;
            talkTimer = 0.4f + (float) Math.random() * 0.3f;
        }
        if (workTimer <= 0) {
            hasWorkTarget = false; // ищем следующее место
        }
        stuckTimer = 0;
    }
}

/**
 * Куда идти работать по профессии: фермер — к грядкам с урожаем,
 * рыбак — к воде, остальные — на рабочее место у здания.
 */
private void findWorkTarget() {
    hasWorkTarget = true;
    if (profession == Profession.FARMER) {
        int[] pos = scanBlock(new BlockType[]{
                BlockType.WHEAT, BlockType.CARROT, BlockType.POTATO},
                WORK_SCAN_RANGE);
        if (pos != null) {
            workTarget.set(pos[0] + 0.5f, position.y, pos[2] + 0.5f);
            return;
        }
    } else if (profession == Profession.FISHERMAN) {
        int[] pos = scanBlock(BlockType.WATER, WORK_SCAN_RANGE);
        if (pos != null) {
            // Встаём на берегу рядом с водой, лицом к ней
            workTarget.set(pos[0] + 0.5f, position.y, pos[2] + 0.5f);
            return;
        }
    }
    workTarget.set(workPos);
}

/** Поиск ближайшего блока одного типа вокруг жителя. */
private int[] scanBlock(BlockType type, float range) {
    return scanBlock(new BlockType[]{type}, range);
}

/** Поиск ближайшего блока одного из типов в кубе вокруг жителя. */
private int[] scanBlock(BlockType[] types, float range) {
    int bx = (int) Math.floor(position.x);
    int by = (int) Math.floor(position.y);
    int bz = (int) Math.floor(position.z);
    float bestSq = range * range;
    int[] best = null;
    int step = 2;
    for (int x = (int) (bx - range); x <= bx + range; x += step) {
        for (int z = (int) (bz - range); z <= bz + range; z += step) {
            for (int y = by - 1; y <= by + 4; y++) {
                byte id = world.getBlock(x, y, z);
                boolean hit = false;
                for (BlockType t : types) {
                    if (id == t.id) {
                        hit = true;
                        break;
                    }
                }
                if (!hit) continue;
                float dx = x - position.x;
                float dz = z - position.z;
                float d = dx * dx + dz * dz;
                if (d < bestSq) {
                    bestSq = d;
                    best = new int[]{x, y, z};
                }
            }
        }
    }
    return best;
}

/**
 * Воин: патрулирует у рабочего места (центр деревни), а когда рядом
 * монстр — бежит к нему и рубит мечом.
 */
private void updateGuard(float dt) {
    if (attackCooldown > 0) attackCooldown -= dt;
    if (attackTimer > 0) attackTimer -= dt;

    if (attackTarget == null || attackTarget.isDead()) {
        attackTarget = findNearestMob(DETECT_RANGE);
    }

    if (attackTarget != null) {
        Vector3f mpos = attackTarget.getPosition();
        float tx = mpos.x - position.x;
        float tz = mpos.z - position.z;
        float dist = (float) Math.sqrt(tx * tx + tz * tz);
        desiredYaw = (float) Math.atan2(-tx, -tz);
        if (dist > ATTACK_RANGE) {
            // Бегом к цели
            moveToward(mpos, getWalkSpeed() * 2.2f, dt);
            if (dangerAhead(dt)) attackTarget = null;
        } else {
            // Встали и бьём мечом
            velocity.x *= 0.7f;
            velocity.z *= 0.7f;
            if (attackCooldown <= 0) {
                attackCooldown = ATTACK_COOLDOWN;
                attackTimer = ATTACK_DURATION;
                float len = Math.max(dist, 0.01f);
                attackTarget.takeDamage(ATTACK_DAMAGE,
                    new Vector3f(-tx / len, 0, -tz / len));
            }
        }
        return;
    }

    // Монстров нет — патрулируем у рабочего места
    if (!hasTarget) {
        pickGuardPost();
    }
    float tx = moveTarget.x - position.x;
    float tz = moveTarget.z - position.z;
    float dist = (float) Math.sqrt(tx * tx + tz * tz);
    if (dist < 0.8f) {
        velocity.x *= 0.8f;
        velocity.z *= 0.8f;
        guardTimer -= dt;
        if (guardTimer <= 0) {
            pickGuardPost(); // следующая точка патруля
        }
    } else {
        desiredYaw = (float) Math.atan2(-tx, -tz);
        moveToward(moveTarget, getWalkSpeed() * 0.9f, dt);
    }
}

/** Следующая точка патруля недалеко от рабочего места (центра деревни). */
private void pickGuardPost() {
    float baseX = hasWork ? workPos.x : (hasHome ? homePos.x : position.x);
    float baseZ = hasWork ? workPos.z : (hasHome ? homePos.z : position.z);
    for (int i = 0; i < 8; i++) {
        float angle = (float) (Math.random() * Math.PI * 2);
        float dist = 2.0f + (float) Math.random() * GUARD_RADIUS;
        float tx = baseX + (float) Math.cos(angle) * dist;
        float tz = baseZ + (float) Math.sin(angle) * dist;
        int g = world.getGroundHeight((int) Math.floor(tx), (int) Math.floor(tz));
        if (g < 1) continue;                         // вода/пустота
        if (Math.abs(g - position.y) > 2.5f) continue; // слишком круто
        moveTarget.set(tx, position.y, tz);
        hasTarget = true;
        guardTimer = 3.0f + (float) Math.random() * 5.0f;
        return;
    }
    moveTarget.set(baseX + 0.5f, position.y, baseZ + 0.5f);
    hasTarget = true;
    guardTimer = 3.0f;
}

